/* Seção 5 — lote de volume. Questões AUTORAIS. */
window.BANCO = window.BANCO || [];
window.BANCO.push(

{ id: 'q-5.1-010', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Um operador de empilhadeira colide com um poste ao voltar para casa dirigindo sua própria motocicleta, logo após o término do turno. O gestor de recursos humanos sustenta que, por se tratar de veículo particular e não de transporte fretado, não há acidente do trabalho. A avaliação tecnicamente CORRETA é:',
  alts: [
    { t: 'Há acidente do trabalho por equiparação, pois o percurso entre o local de trabalho e a residência é protegido qualquer que seja o meio de locomoção, inclusive veículo de propriedade do próprio trabalhador.', ok: true,
      why: 'Correta. A proteção do percurso não distingue meio de locomoção nem exige que o transporte seja fornecido ou custeado pela empresa.' },
    { t: 'Não há acidente do trabalho, pois a proteção do percurso alcança apenas o transporte fornecido pela empresa.', ok: false,
      why: 'Errada. Condicionar a proteção ao transporte fornecido pela empresa é justamente a restrição que a lei não faz.' },
    { t: 'Há acidente do trabalho apenas se o trabalhador comprovar que não houve culpa sua na condução do veículo.', ok: false,
      why: 'Errada. A caracterização do acidente do trabalho não depende de apuração de culpa do trabalhador; culpa interessa à discussão de responsabilidade civil, não à caracterização previdenciária.' },
    { t: 'Não há acidente do trabalho porque o evento ocorreu depois do encerramento da jornada contratual.', ok: false,
      why: 'Errada. O percurso é protegido exatamente por ocorrer fora da jornada; se estivesse dentro dela seria acidente típico, e não equiparado.' },
    { t: 'Há acidente do trabalho somente se o trajeto tiver sido percorrido pelo caminho mais curto entre os dois pontos.', ok: false,
      why: 'Errada. Não existe exigência de itinerário mínimo; o que se avalia é a compatibilidade do percurso com o deslocamento entre residência e trabalho.' }
  ],
  comentario: 'O acidente de percurso é equiparado a acidente do trabalho e a proteção independe do meio de locomoção e de quem fornece ou custeia o transporte. Culpa do trabalhador e horário fora da jornada não descaracterizam a equiparação.',
  pegadinha: 'A banca insere a condicionante "desde que o transporte seja fornecido pela empresa", que soa razoável e é falsa.',
  refs: ['Lei nº 8.213/1991 — art. 21', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-011', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Durante discussão sobre a divisão de tarefas na linha de montagem, um trabalhador agride fisicamente um colega, que sofre fratura de ossos próprios do nariz. O evento ocorreu dentro da fábrica, em pleno horário de trabalho. A conduta correta quanto à caracterização é:',
  alts: [
    { t: 'Caracteriza acidente do trabalho por equiparação, pois a ofensa física intencional praticada por companheiro de trabalho no local e horário de trabalho está entre as hipóteses legalmente equiparadas.', ok: true,
      why: 'Correta. A agressão por companheiro de trabalho no local e horário laboral é hipótese expressa de equiparação, ainda mais quando motivada por disputa relacionada ao serviço.' },
    { t: 'Não caracteriza acidente do trabalho, pois a lesão decorreu de conduta dolosa de terceiro e não do exercício da atividade.', ok: false,
      why: 'Errada. A lei equipara expressamente o dano resultante de ato de terceiro, inclusive doloso, ocorrido no local e horário de trabalho.' },
    { t: 'Caracteriza acidente do trabalho apenas se o agressor for punido disciplinarmente pela empresa.', ok: false,
      why: 'Errada. A caracterização previdenciária não depende de apuração disciplinar interna nem de sanção ao agressor.' },
    { t: 'Não caracteriza acidente do trabalho, pois a motivação foi interpessoal, e não técnica.', ok: false,
      why: 'Errada. A equiparação alcança a agressão no local e horário de trabalho ainda que a motivação não seja diretamente relacionada à tarefa.' },
    { t: 'Caracteriza acidente do trabalho somente se resultar afastamento superior a quinze dias.', ok: false,
      why: 'Errada. A duração do afastamento define repercussões de benefício, não a caracterização do acidente.' }
  ],
  comentario: 'Ato de terceiro ou de companheiro de trabalho no local e horário laboral é hipótese clássica de equiparação, incluindo agressão, sabotagem, imprudência de colega e brincadeiras. A caracterização não depende de culpa, de apuração disciplinar nem da extensão do afastamento.',
  pegadinha: 'O argumento de que "foi briga pessoal, não é acidente" é sedutor e falso: o que importa é o local e o horário de trabalho.',
  refs: ['Lei nº 8.213/1991 — art. 21', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-012', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Uma auxiliar de produção escorrega no piso molhado do refeitório da própria empresa durante o intervalo intrajornada e sofre fratura de punho. A empresa alega que, por estar em horário de descanso não remunerado, não há acidente do trabalho. A orientação correta é:',
  alts: [
    { t: 'Há acidente do trabalho, pois os períodos de refeição e descanso no local de trabalho são considerados como de exercício do trabalho para fins de caracterização.', ok: true,
      why: 'Correta. A lei considera o trabalhador no exercício do trabalho durante refeição, descanso e satisfação de necessidades fisiológicas no local de trabalho.' },
    { t: 'Não há acidente do trabalho, pois o intervalo intrajornada não é computado na jornada e afasta a proteção acidentária.', ok: false,
      why: 'Errada. O tratamento do intervalo para efeito de duração da jornada não se confunde com a proteção acidentária, que alcança expressamente esse período no local de trabalho.' },
    { t: 'Há acidente do trabalho apenas se a refeição for fornecida pela empresa em programa formal de alimentação.', ok: false,
      why: 'Errada. A proteção decorre de o evento ocorrer no local de trabalho durante o período de refeição, e não da existência de programa de alimentação.' },
    { t: 'Não há acidente do trabalho porque a queda decorreu de condição do piso, e não da atividade exercida.', ok: false,
      why: 'Errada. Condições do ambiente de trabalho são causa típica de acidente; o argumento inverteria a lógica da proteção.' },
    { t: 'Há acidente do trabalho somente se a trabalhadora estiver uniformizada no momento do evento.', ok: false,
      why: 'Errada. Uso de uniforme não é elemento de caracterização de acidente do trabalho.' }
  ],
  comentario: 'Refeição, descanso e satisfação de necessidade fisiológica no local de trabalho são equiparados ao exercício do trabalho. É uma das hipóteses de equiparação mais cobradas porque contraria a intuição de que "fora da jornada não conta".',
  pegadinha: 'A menção ao intervalo "não remunerado" é isca: a proteção acidentária não segue a lógica de remuneração da jornada.',
  refs: ['Lei nº 8.213/1991 — art. 21', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-013', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Um soldador dirige-se ao sanitário da fábrica durante o expediente, tropeça em desnível do piso e sofre entorse grave de joelho, com afastamento de trinta dias. Assinale a alternativa CORRETA quanto ao enquadramento e às providências:',
  alts: [
    { t: 'Trata-se de acidente do trabalho, pois a satisfação de necessidade fisiológica no local de trabalho é considerada exercício do trabalho, cabendo emissão de comunicação de acidente e benefício de natureza acidentária.', ok: true,
      why: 'Correta. O evento se enquadra na equiparação; com afastamento prolongado, o benefício terá natureza acidentária e há repercussão em estabilidade e recolhimento de fundo de garantia.' },
    { t: 'Trata-se de acidente comum, pois o deslocamento ao sanitário interrompe o exercício do trabalho.', ok: false,
      why: 'Errada. A lei considera exatamente o oposto: durante a necessidade fisiológica no local de trabalho, o trabalhador é tido como no exercício do trabalho.' },
    { t: 'Trata-se de acidente do trabalho, mas a comunicação só será devida após a perícia reconhecer o nexo.', ok: false,
      why: 'Errada. A comunicação antecede e independe do reconhecimento pericial; a perícia analisa o benefício, não autoriza a comunicação.' },
    { t: 'Trata-se de acidente do trabalho apenas para fins estatísticos, sem repercussão previdenciária.', ok: false,
      why: 'Errada. A caracterização acidentária tem repercussão previdenciária concreta na espécie do benefício e em direitos acessórios.' },
    { t: 'Trata-se de acidente de trajeto interno, categoria própria que dispensa comunicação.', ok: false,
      why: 'Errada. Não existe essa categoria; o percurso protegido é o que se dá entre residência e trabalho, e nenhuma hipótese de acidente do trabalho dispensa comunicação.' }
  ],
  comentario: 'A equiparação abrange a necessidade fisiológica no local de trabalho. Reconhecido o acidente, a comunicação é imediata e independe da perícia, e o afastamento superior a quinze dias gera benefício de natureza acidentária, com repercussão em estabilidade e fundo de garantia.',
  pegadinha: 'Condicionar a emissão da comunicação ao resultado da perícia inverte a ordem dos atos e é erro recorrente.',
  refs: ['Lei nº 8.213/1991 — arts. 21 e 22', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-014', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Um consultor técnico viaja a outro estado para prestar serviço a cliente da empresa. No hotel, à noite, sofre queda na escada e fratura o cotovelo. A caracterização adequada do evento é:',
  alts: [
    { t: 'Acidente do trabalho, pois a viagem a serviço da empresa é hipótese de equiparação, qualquer que seja o meio de locomoção, e o trabalhador permanece sob proteção durante o deslocamento a serviço.', ok: true,
      why: 'Correta. A viagem a serviço está entre as hipóteses de equiparação, e a proteção não se limita ao instante da execução da tarefa contratada.' },
    { t: 'Acidente comum, pois o evento ocorreu em hotel, fora do estabelecimento da empresa e fora do horário contratual.', ok: false,
      why: 'Errada. A equiparação da viagem a serviço existe justamente para alcançar eventos fora do estabelecimento e do horário habitual.' },
    { t: 'Acidente do trabalho apenas se a viagem tiver sido realizada em veículo da empresa.', ok: false,
      why: 'Errada. A equiparação da viagem a serviço independe do meio de locomoção utilizado.' },
    { t: 'Acidente de trajeto, por se tratar de deslocamento entre dois pontos.', ok: false,
      why: 'Errada. O percurso protegido é o de residência para o trabalho e vice-versa; deslocamento a serviço tem enquadramento próprio.' },
    { t: 'Acidente comum, pois não havia ordem expressa e escrita da empresa para a permanência no hotel.', ok: false,
      why: 'Errada. A hospedagem é decorrência lógica da viagem a serviço; exigir ordem escrita específica não tem amparo legal.' }
  ],
  comentario: 'Viagem a serviço, inclusive para estudo custeado pela empresa dentro de seus planos de capacitação, é hipótese de equiparação. A proteção acompanha o trabalhador durante o deslocamento e não se restringe ao momento exato da tarefa.',
  pegadinha: 'Confundir viagem a serviço com percurso residência-trabalho é o erro conceitual mais comum neste cenário.',
  refs: ['Lei nº 8.213/1991 — art. 21', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-015', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Um técnico de manutenção, já de folga em casa, é chamado por telefone pelo supervisor para atender emergência em cliente. A caminho do cliente, sofre colisão e fratura de fêmur. Sobre a caracterização, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Há acidente do trabalho, pois o evento ocorreu fora do local e do horário de trabalho, porém na execução de ordem ou na realização de serviço a cargo da empresa.', ok: true,
      why: 'Correta. A execução de ordem ou de serviço da empresa fora do local e do horário habituais é hipótese expressa de equiparação.' },
    { t: 'Não há acidente do trabalho, pois o trabalhador estava em período de folga não remunerado.', ok: false,
      why: 'Errada. Estar em folga é irrelevante quando o trabalhador se desloca em cumprimento de ordem da empresa.' },
    { t: 'Há acidente de trajeto, pois o deslocamento partiu da residência do trabalhador.', ok: false,
      why: 'Errada. O ponto de partida não define o enquadramento: aqui o deslocamento é para executar serviço, e não o percurso habitual casa-trabalho.' },
    { t: 'Não há acidente do trabalho, pois a ordem foi verbal e não há registro documental do chamado.', ok: false,
      why: 'Errada. A forma da ordem não é requisito legal; a ordem verbal pode ser comprovada por outros meios.' },
    { t: 'Há acidente do trabalho apenas se o regime de sobreaviso estiver previsto em acordo coletivo.', ok: false,
      why: 'Errada. A previsão contratual de sobreaviso repercute em remuneração, e não na caracterização do acidente.' }
  ],
  comentario: 'A equiparação alcança o acidente sofrido fora do local e do horário de trabalho na execução de ordem ou na prestação de serviço sob autoridade da empresa. É a hipótese que resolve os casos de chamado, plantão e atendimento externo.',
  pegadinha: 'Enquadrar o caso como acidente de trajeto parece inofensivo, mas troca a hipótese legal e costuma ser a distratora escolhida.',
  refs: ['Lei nº 8.213/1991 — art. 21', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-016', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Forte enxurrada provoca alagamento e desabamento de parte do galpão de uma indústria, ferindo três trabalhadores durante o expediente. A empresa argumenta que se trata de força maior, sem relação com a atividade produtiva. A conclusão CORRETA é:',
  alts: [
    { t: 'São acidentes do trabalho, pois desabamento, inundação, incêndio e outros casos fortuitos ou de força maior ocorridos no local de trabalho estão entre as hipóteses equiparadas.', ok: true,
      why: 'Correta. A lei equipara expressamente os eventos de caso fortuito ou força maior ocorridos no local de trabalho.' },
    { t: 'Não são acidentes do trabalho, pois força maior rompe qualquer nexo com a atividade da empresa.', ok: false,
      why: 'Errada. Força maior é hipótese expressamente incluída, e não excludente, quando o evento ocorre no local de trabalho.' },
    { t: 'São acidentes do trabalho apenas se ficar comprovada falha de manutenção predial.', ok: false,
      why: 'Errada. A comprovação de falha interessa à responsabilidade civil e à ação regressiva, não à caracterização do acidente.' },
    { t: 'Não são acidentes do trabalho, mas devem ser notificados à vigilância em saúde como evento ambiental.', ok: false,
      why: 'Errada. São acidentes do trabalho e, sendo graves, também devem ser notificados à vigilância — os fluxos são cumulativos, não alternativos.' },
    { t: 'São acidentes do trabalho somente para os trabalhadores que estavam executando tarefa no momento do desabamento.', ok: false,
      why: 'Errada. A equiparação alcança quem estava no local de trabalho, inclusive em pausa ou deslocamento interno.' }
  ],
  comentario: 'Caso fortuito e força maior no local de trabalho não afastam a caracterização: a lei os inclui entre as hipóteses equiparadas. Culpa e falha de manutenção pertencem à discussão de responsabilidade, não à caracterização.',
  pegadinha: 'A palavra "força maior" ativa em muitos candidatos a ideia de exclusão de responsabilidade, que não se aplica à caracterização acidentária.',
  refs: ['Lei nº 8.213/1991 — art. 21', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-017', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre as hipóteses legalmente equiparadas a acidente do trabalho, assinale a alternativa INCORRETA:',
  alts: [
    { t: 'O acidente ocorrido no percurso entre a residência e o local de trabalho só é equiparado quando o transporte é fornecido pela empresa ou quando o trabalhador utiliza transporte coletivo regular.', ok: true,
      why: 'Esta é a afirmação falsa, e por isso deve ser marcada. A proteção do percurso independe do meio de locomoção e de quem fornece o transporte, alcançando inclusive veículo do próprio trabalhador.' },
    { t: 'A ofensa física intencional praticada por companheiro de trabalho, no local e horário de trabalho, equipara-se a acidente do trabalho.', ok: false,
      why: 'Afirmação verdadeira. Ato de terceiro ou de companheiro no local e horário laboral é hipótese expressa de equiparação.' },
    { t: 'O acidente sofrido durante a satisfação de necessidade fisiológica no local de trabalho equipara-se, pois nesses períodos o trabalhador é considerado no exercício do trabalho.', ok: false,
      why: 'Afirmação verdadeira, e uma das hipóteses mais cobradas em prova.' },
    { t: 'Equipara-se o acidente sofrido em viagem a serviço da empresa, inclusive para estudo custeado por ela dentro de seus planos de capacitação.', ok: false,
      why: 'Afirmação verdadeira. A viagem a serviço, inclusive para capacitação financiada pela empresa, é hipótese equiparada.' },
    { t: 'Equipara-se o acidente decorrente de ato de imprudência, negligência ou imperícia de terceiro ou de companheiro de trabalho.', ok: false,
      why: 'Afirmação verdadeira. Culpa de terceiro é hipótese expressamente equiparada.' }
  ],
  comentario: 'A lista de equiparações é ampla: doença profissional e do trabalho, ato de terceiro ou de companheiro, sabotagem, caso fortuito e força maior no local, execução de ordem fora do local e horário, viagem a serviço, percurso residência-trabalho e períodos de refeição, descanso e necessidade fisiológica no local.',
  pegadinha: 'A restrição inventada sobre o meio de transporte no percurso é a distorção mais frequente da lista de equiparações.',
  refs: ['Lei nº 8.213/1991 — art. 21', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-018', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Um açougueiro sofre corte superficial no antebraço com faca de desossa, recebe curativo no ambulatório e retorna ao posto no mesmo turno, sem qualquer afastamento. O supervisor pergunta ao médico do trabalho se é preciso comunicar o evento. A resposta CORRETA é:',
  alts: [
    { t: 'A comunicação é devida, pois a obrigação de comunicar não depende de haver afastamento, e o registro cumpre também finalidade estatística e de vigilância.', ok: true,
      why: 'Correta. A comunicação é obrigatória mesmo em acidente sem afastamento; a existência de afastamento repercute no benefício, não na obrigação de comunicar.' },
    { t: 'A comunicação é dispensada, pois sem afastamento não há repercussão previdenciária a documentar.', ok: false,
      why: 'Errada. Mesmo sem repercussão imediata em benefício, o registro é obrigatório e resguarda direitos futuros do trabalhador.' },
    { t: 'A comunicação só será devida se houver agravamento posterior da lesão.', ok: false,
      why: 'Errada. O agravamento posterior enseja comunicação de reabertura, mas não substitui a comunicação inicial devida desde logo.' },
    { t: 'A comunicação é substituída pelo registro em prontuário do ambulatório da empresa.', ok: false,
      why: 'Errada. O prontuário é documento assistencial e não cumpre a função legal da comunicação de acidente.' },
    { t: 'A comunicação depende de solicitação formal do trabalhador ou do sindicato.', ok: false,
      why: 'Errada. A obrigação primária é da empresa e independe de provocação; os demais legitimados atuam de forma subsidiária.' }
  ],
  comentario: 'Acidente sem afastamento também gera comunicação. Além de resguardar direitos do trabalhador em caso de agravamento futuro, o registro alimenta indicadores de acidentalidade e a vigilância. Prontuário não substitui comunicação.',
  pegadinha: 'A associação automática entre "sem afastamento" e "sem comunicação" é o erro mais frequente do tema.',
  refs: ['Lei nº 8.213/1991 — art. 22', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-019', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Um trabalhador da construção civil sofre queda de altura e morre no local, às 16 horas de uma sexta-feira. O setor administrativo pergunta ao médico do trabalho qual o prazo para a comunicação do acidente. A orientação CORRETA é:',
  alts: [
    { t: 'Em caso de morte, a comunicação deve ser feita de imediato, inclusive à autoridade competente, não se aplicando o prazo do primeiro dia útil seguinte que vale para os demais acidentes.', ok: true,
      why: 'Correta. O óbito impõe comunicação imediata, além da comunicação à autoridade competente; o prazo até o primeiro dia útil seguinte é a regra geral dos demais casos.' },
    { t: 'O prazo é até o primeiro dia útil seguinte, uma vez que a regra é única para todos os acidentes.', ok: false,
      why: 'Errada. A morte tem tratamento próprio, com comunicação imediata.' },
    { t: 'O prazo é de até quinze dias, coincidindo com o período de responsabilidade da empresa pelo pagamento nos afastamentos.', ok: false,
      why: 'Errada. O intervalo de quinze dias diz respeito à responsabilidade pelo pagamento no afastamento, e não a prazo de comunicação.' },
    { t: 'A comunicação deve aguardar a conclusão do laudo necroscópico para que a causa seja informada corretamente.', ok: false,
      why: 'Errada. A comunicação é imediata; dados complementares podem ser agregados depois, mas não se aguarda laudo para comunicar.' },
    { t: 'Não há comunicação em caso de óbito, bastando o registro do fato pela autoridade policial.', ok: false,
      why: 'Errada. Existe modalidade específica de comunicação para o óbito, que não é substituída pelo registro policial.' }
  ],
  comentario: 'Regra geral: comunicação até o primeiro dia útil seguinte ao da ocorrência. Em caso de morte: de imediato, inclusive à autoridade competente. Existem três modalidades de comunicação — inicial, de reabertura e de comunicação de óbito.',
  pegadinha: 'A distratora dos quinze dias explora a confusão entre prazo de comunicação e período de responsabilidade da empresa pelo pagamento.',
  refs: ['Lei nº 8.213/1991 — art. 22', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-020', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhadora com tenossinovite de punho reconhecida como relacionada ao trabalho solicita à empresa a emissão da comunicação de acidente, que se recusa por entender que o quadro é degenerativo. Passados dois meses, procura o serviço público de saúde. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'A comunicação pode ser emitida pelo médico assistente, pela própria trabalhadora, por seus dependentes, pelo sindicato ou por qualquer autoridade pública, e para esses legitimados não prevalece prazo.', ok: true,
      why: 'Correta. Diante da omissão da empresa, a lei confere legitimidade subsidiária a esses atores, expressamente afastando a preclusão de prazo.' },
    { t: 'Somente a empresa pode emitir a comunicação, restando à trabalhadora a via judicial.', ok: false,
      why: 'Errada. A obrigação primária é da empresa, mas a lei prevê legitimados subsidiários exatamente para o caso de omissão.' },
    { t: 'A comunicação não pode mais ser emitida, pois expirou o prazo do primeiro dia útil seguinte.', ok: false,
      why: 'Errada. O prazo vincula a empresa; para os legitimados subsidiários a lei afasta expressamente a prevalência de prazo.' },
    { t: 'O médico assistente só pode comunicar mediante autorização escrita da empresa empregadora.', ok: false,
      why: 'Errada. A legitimidade do médico assistente é autônoma e não depende de anuência do empregador.' },
    { t: 'A discordância técnica da empresa quanto ao nexo impede a emissão por qualquer outro legitimado.', ok: false,
      why: 'Errada. A recusa da empresa é precisamente o pressuposto que aciona a legitimidade subsidiária.' }
  ],
  comentario: 'Legitimados subsidiários: o próprio acidentado, seus dependentes, a entidade sindical, o médico assistente e qualquer autoridade pública. Para eles não prevalece prazo, o que permite regularizar situações de subnotificação meses depois.',
  pegadinha: 'A ideia de que o prazo perdido extingue o direito de comunicar é falsa e é a distratora mais escolhida.',
  refs: ['Lei nº 8.213/1991 — art. 22', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-021', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'A gerência de uma transportadora orienta o serviço médico a só emitir comunicações de acidente depois que a perícia previdenciária reconhecer o nexo, para "evitar comunicações indevidas". Sobre essa orientação, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A orientação é tecnicamente incorreta: a comunicação antecede e independe do reconhecimento pericial, cabendo à perícia decidir sobre o benefício, e não autorizar a comunicação.', ok: true,
      why: 'Correta. A comunicação é ato de registro obrigatório do empregador; o juízo pericial é posterior e tem outra finalidade.' },
    { t: 'A orientação é adequada, pois comunicar antes do reconhecimento pericial gera passivo indevido para a empresa.', ok: false,
      why: 'Errada. O receio de passivo não autoriza descumprir obrigação legal de registro, e a omissão sujeita a empresa a penalidade.' },
    { t: 'A orientação é adequada apenas nos acidentes sem afastamento.', ok: false,
      why: 'Errada. Acidentes sem afastamento também são comunicados, e igualmente sem depender da perícia.' },
    { t: 'A orientação é correta porque o médico do trabalho não pode firmar nexo, atribuição exclusiva da perícia.', ok: false,
      why: 'Errada. O médico do trabalho e o assistente estabelecem nexo para fins clínicos e de comunicação; o reconhecimento para fins de benefício é que compete à perícia.' },
    { t: 'A orientação é correta desde que a empresa registre o evento em livro interno enquanto aguarda a perícia.', ok: false,
      why: 'Errada. Registro interno não substitui a comunicação legal nem suspende o prazo do empregador.' }
  ],
  comentario: 'A comunicação é obrigação de registro, imediata e independente de perícia, de afastamento e de concordância da empresa quanto ao nexo. Conceber a comunicação como "reconhecimento de culpa" é erro de gestão que a prova cobra como erro técnico.',
  pegadinha: 'A frase "só o perito pode falar em nexo" é falsa e aparece disfarçada de rigor técnico.',
  refs: ['Lei nº 8.213/1991 — arts. 21-A e 22', 'Guia 5.2 — Nexo Causal'] },

{ id: 'q-5.1-022', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador que teve comunicação de acidente emitida há dois anos por lesão de ombro, já com alta, apresenta agravamento da sequela e necessita reiniciar tratamento e afastar-se novamente. A providência documental adequada é:',
  alts: [
    { t: 'Emitir comunicação de reabertura, modalidade destinada ao reinício de tratamento ou ao agravamento de sequela de acidente já comunicado.', ok: true,
      why: 'Correta. A reabertura é a modalidade prevista exatamente para reinício de tratamento ou agravamento de lesão decorrente de evento já registrado.' },
    { t: 'Emitir nova comunicação inicial, pois cada afastamento constitui evento autônomo.', ok: false,
      why: 'Errada. Não se trata de novo evento, e sim de desdobramento do acidente já comunicado, o que caracteriza reabertura.' },
    { t: 'Não emitir comunicação, pois o evento original já foi registrado e o registro é único.', ok: false,
      why: 'Errada. A existência da comunicação inicial não dispensa a de reabertura quando há novo afastamento por agravamento.' },
    { t: 'Emitir apenas atestado médico, pois a modalidade de reabertura foi extinta com a comunicação eletrônica.', ok: false,
      why: 'Errada. As modalidades permanecem, apenas migraram de suporte documental para transmissão eletrônica.' },
    { t: 'Emitir comunicação de óbito prospectiva, por se tratar de sequela definitiva.', ok: false,
      why: 'Errada. A modalidade de comunicação de óbito destina-se ao falecimento decorrente do acidente, e não a sequelas.' }
  ],
  comentario: 'Três modalidades: inicial (evento novo), reabertura (reinício de tratamento ou agravamento de lesão já comunicada) e comunicação de óbito. A migração para transmissão eletrônica não alterou as modalidades nem os prazos.',
  pegadinha: 'Emitir comunicação inicial para agravamento de lesão antiga quebra a rastreabilidade do caso e é o erro mais comum.',
  refs: ['Lei nº 8.213/1991 — art. 22', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-023', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Um hospital registra acidente com material biológico envolvendo técnica de enfermagem. O setor de segurança do trabalho informa que já realizou a notificação do agravo no sistema de informação de agravos e, por isso, não emitirá a comunicação de acidente. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'Os dois registros têm finalidades distintas e são cumulativos: a comunicação de acidente cumpre finalidade previdenciária e a notificação cumpre finalidade de vigilância em saúde, não havendo substituição de um pelo outro.', ok: true,
      why: 'Correta. Os fluxos são independentes e não excludentes; deixar de emitir a comunicação priva o trabalhador de repercussões previdenciárias.' },
    { t: 'A notificação no sistema de agravos substitui a comunicação de acidente, por conter os mesmos dados clínicos.', ok: false,
      why: 'Errada. Coincidência parcial de dados não gera substituição: os destinatários e as finalidades dos registros são diferentes.' },
    { t: 'A comunicação de acidente substitui a notificação, pois alimenta as estatísticas oficiais de acidentalidade.', ok: false,
      why: 'Errada. A inversão também é falsa; a vigilância em saúde depende da notificação no sistema próprio.' },
    { t: 'A notificação só é devida se houver soroconversão comprovada do trabalhador.', ok: false,
      why: 'Errada. O acidente com material biológico é notificável independentemente do desfecho sorológico.' },
    { t: 'Nenhum dos dois registros é devido quando o trabalhador não se afasta do serviço.', ok: false,
      why: 'Errada. Ausência de afastamento não dispensa nem a comunicação previdenciária nem a notificação em vigilância.' }
  ],
  comentario: 'Comunicação de acidente e notificação em sistema de agravos são fluxos distintos e cumulativos: previdência e vigilância em saúde. Acidente com material biológico é exemplo clássico em que ambos são devidos, mesmo sem afastamento e antes de qualquer desfecho sorológico.',
  pegadinha: 'A ideia de "um registro basta" é a armadilha; a prova testa se o candidato sabe que os sistemas não conversam entre si para essa finalidade.',
  refs: ['Lei nº 8.213/1991 — art. 22', 'Portaria de notificação compulsória — agravos relacionados ao trabalho'] },

{ id: 'q-5.1-024', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre a Comunicação de Acidente do Trabalho, todas as afirmações abaixo são verdadeiras, EXCETO:',
  alts: [
    { t: 'A emissão é ato privativo do médico do trabalho da empresa, sendo vedada a sua emissão por qualquer outro profissional ou entidade.', ok: true,
      why: 'Esta é a afirmação falsa, e por isso deve ser marcada. A obrigação primária é da empresa, e há legitimados subsidiários — inclusive o próprio acidentado e o sindicato, que não são médicos.' },
    { t: 'A obrigação de comunicar independe de haver afastamento do trabalho.', ok: false,
      why: 'Afirmação verdadeira e frequentemente cobrada.' },
    { t: 'A comunicação independe do prévio reconhecimento do nexo pela perícia previdenciária.', ok: false,
      why: 'Afirmação verdadeira. O registro antecede e não se subordina ao juízo pericial.' },
    { t: 'O descumprimento da obrigação sujeita a empresa a multa administrativa.', ok: false,
      why: 'Afirmação verdadeira. A omissão é infração sancionada administrativamente.' },
    { t: 'Existem modalidades de comunicação inicial, de reabertura e de óbito.', ok: false,
      why: 'Afirmação verdadeira. São as três modalidades previstas.' }
  ],
  comentario: 'A emissão não é ato privativo de médico: a obrigação é da empresa e, subsidiariamente, do acidentado, dependentes, sindicato, médico assistente e autoridade pública. Ao médico cabe a caracterização técnica, não o monopólio do registro.',
  pegadinha: 'Atribuir exclusividade ao médico do trabalho lisonjeia a especialidade e por isso engana; a lei distribui a legitimidade.',
  refs: ['Lei nº 8.213/1991 — art. 22', 'Guia 5.1 — Acidentes do Trabalho'] }
,

{ id: 'q-5.1-025', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Um empregado afastou-se por oito meses em razão de acidente do trabalho, recebendo benefício de natureza acidentária, e teve alta pericial em 10 de março. A empresa consulta o médico do trabalho sobre a contagem da garantia de emprego. A informação CORRETA é:',
  alts: [
    { t: 'A garantia de manutenção do contrato é de no mínimo doze meses contados da cessação do benefício acidentário, ou seja, a partir da alta pericial.', ok: true,
      why: 'Correta. O marco inicial da contagem é a cessação do benefício, e não o início do afastamento nem a data do acidente.' },
    { t: 'A garantia é de doze meses contados da data do acidente, já incluídos os meses de afastamento.', ok: false,
      why: 'Errada. Contar da data do acidente absorveria o período de afastamento e esvaziaria a finalidade do instituto, que é proteger a reinserção após a alta.' },
    { t: 'A garantia é de doze meses contados do início do afastamento previdenciário.', ok: false,
      why: 'Errada. É a troca de marco inicial mais explorada em prova: conta-se da cessação, não do início.' },
    { t: 'A garantia existe apenas se o trabalhador passar a receber auxílio-acidente após a alta.', ok: false,
      why: 'Errada. A garantia independe da concessão de auxílio-acidente; são institutos distintos e não cumulativamente exigidos.' },
    { t: 'A garantia é de seis meses contados da alta, prorrogáveis por igual período mediante negociação coletiva.', ok: false,
      why: 'Errada. O prazo mínimo legal é de doze meses e não depende de negociação coletiva para existir.' }
  ],
  comentario: 'Estabilidade acidentária: prazo mínimo de doze meses contados da cessação do benefício acidentário, independentemente da percepção de auxílio-acidente. O erro clássico é deslocar o marco inicial para a data do acidente ou do início do afastamento.',
  pegadinha: 'A banca mantém o prazo correto e troca apenas o marco inicial — quem decorou "doze meses" sem o marco erra.',
  refs: ['Lei nº 8.213/1991 — art. 118', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-026', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Após alta de benefício acidentário, um trabalhador retorna às suas funções sem sequelas e sem redução de capacidade, não fazendo jus a auxílio-acidente. O setor jurídico da empresa entende que, por não haver auxílio-acidente, também não há garantia de emprego. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'A garantia de emprego decorre do afastamento com benefício acidentário e independe da concessão de auxílio-acidente, que é benefício distinto e de pressupostos próprios.', ok: true,
      why: 'Correta. São institutos autônomos: um protege a reinserção após a alta, o outro indeniza a redução permanente de capacidade.' },
    { t: 'O entendimento do setor jurídico é correto, pois o auxílio-acidente é o pressuposto da garantia de emprego.', ok: false,
      why: 'Errada. A lei não condiciona a garantia à concessão de auxílio-acidente.' },
    { t: 'A garantia só existe quando permanece incapacidade parcial permanente comprovada em nova perícia.', ok: false,
      why: 'Errada. Sequela permanente não é requisito da garantia de emprego decorrente do afastamento acidentário.' },
    { t: 'A garantia existe, mas o prazo é reduzido pela metade quando não há sequela.', ok: false,
      why: 'Errada. Não existe redução proporcional do prazo em função da presença ou ausência de sequela.' },
    { t: 'A garantia se converte em indenização substitutiva automática quando não há auxílio-acidente.', ok: false,
      why: 'Errada. Indenização substitutiva é consequência de descumprimento da garantia, e não regra automática de conversão.' }
  ],
  comentario: 'Garantia de emprego pós-alta e auxílio-acidente respondem a lógicas diferentes: a primeira preserva o vínculo por período mínimo após a cessação do benefício; o segundo indeniza sequela consolidada que reduz a capacidade. A existência de um não é condição do outro.',
  pegadinha: 'Vincular a estabilidade ao auxílio-acidente parece coerente e é falso; a prova cobra a autonomia dos institutos.',
  refs: ['Lei nº 8.213/1991 — arts. 86 e 118', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-027', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Sobre as repercussões do reconhecimento da natureza acidentária de um afastamento, assinale a alternativa INCORRETA:',
  alts: [
    { t: 'O benefício acidentário exige o cumprimento de carência mínima de doze contribuições mensais, tal como o benefício por incapacidade de origem comum.', ok: true,
      why: 'Esta é a afirmação falsa, e por isso deve ser marcada. Os benefícios decorrentes de acidente do trabalho e de doença ocupacional dispensam carência.' },
    { t: 'Durante o afastamento acidentário, mantém-se o recolhimento do fundo de garantia pelo empregador.', ok: false,
      why: 'Afirmação verdadeira, e uma das principais diferenças práticas em relação ao afastamento por doença comum.' },
    { t: 'Após a cessação do benefício acidentário, o contrato de trabalho é mantido por período mínimo de doze meses.', ok: false,
      why: 'Afirmação verdadeira. É a garantia de emprego contada da cessação do benefício.' },
    { t: 'O reconhecimento da natureza acidentária pode repercutir na alíquota de contribuição da empresa destinada ao financiamento dos benefícios acidentários.', ok: false,
      why: 'Afirmação verdadeira. O desempenho acidentário da empresa influencia o multiplicador aplicado sobre a alíquota.' },
    { t: 'A Previdência pode propor ação regressiva contra a empresa quando houver negligência quanto às normas de segurança e saúde no trabalho.', ok: false,
      why: 'Afirmação verdadeira. A ação regressiva busca ressarcir os gastos previdenciários decorrentes da negligência empresarial.' }
  ],
  comentario: 'Reconhecida a natureza acidentária, decorrem: dispensa de carência, manutenção do fundo de garantia no afastamento, garantia de emprego após a alta, repercussão na alíquota de financiamento e possibilidade de ação regressiva. Exigir carência nesse contexto é o erro plantado.',
  pegadinha: 'A carência é exigida no benefício por incapacidade de origem comum, mas dispensada quando a origem é acidentária ou ocupacional.',
  refs: ['Lei nº 8.213/1991 — arts. 26, 118 e 120', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-028', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Um trabalhador é dispensado sem justa causa e, dois meses depois, recebe diagnóstico de doença ocupacional cuja relação com a atividade exercida na antiga empregadora é tecnicamente demonstrada. Sobre a garantia de emprego, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A garantia pode ser reconhecida quando se constata, após a dispensa, doença ocupacional que guarde relação de causalidade com o trabalho executado, ainda que não tenha havido afastamento anterior.', ok: true,
      why: 'Correta. A jurisprudência trabalhista consolidada admite a garantia nessa hipótese, justamente porque o diagnóstico costuma ser tardio nas doenças ocupacionais.' },
    { t: 'A garantia é impossível, pois exige sempre afastamento prévio superior a quinze dias com percepção de benefício acidentário.', ok: false,
      why: 'Errada. Essa é a regra geral, mas a doença ocupacional constatada após a dispensa é exceção reconhecida.' },
    { t: 'A garantia só se aplica a acidente típico, nunca a doença ocupacional.', ok: false,
      why: 'Errada. Doença profissional e do trabalho são equiparadas a acidente do trabalho para todos os efeitos.' },
    { t: 'A garantia depende de a empresa ter emitido comunicação de acidente antes da dispensa.', ok: false,
      why: 'Errada. A omissão da empresa no registro não pode ser convertida em obstáculo ao direito do trabalhador.' },
    { t: 'A garantia é substituída, nesse caso, pela concessão automática de aposentadoria por incapacidade permanente.', ok: false,
      why: 'Errada. Aposentadoria por incapacidade permanente exige incapacidade total e definitiva insuscetível de reabilitação, o que não é sequer aventado no cenário.' }
  ],
  comentario: 'A regra geral da garantia pressupõe afastamento com benefício acidentário, mas o diagnóstico tardio de doença ocupacional após a dispensa é hipótese reconhecida — coerente com a latência típica das doenças relacionadas ao trabalho.',
  pegadinha: 'Aplicar mecanicamente a regra geral ignora a exceção construída exatamente para as doenças de manifestação tardia.',
  refs: ['Lei nº 8.213/1991 — arts. 20 e 118', 'Jurisprudência trabalhista consolidada sobre estabilidade acidentária'] },

{ id: 'q-5.1-029', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Após amputação de dedo em prensa, a investigação conduzida pela empresa conclui como causa raiz o "ato inseguro do operador, que introduziu a mão na zona de risco", e propõe como medida a reciclagem do treinamento. O médico do trabalho é consultado sobre a qualidade dessa investigação. A crítica tecnicamente CORRETA é:',
  alts: [
    { t: 'A investigação é incompleta, pois encerra a análise no comportamento do trabalhador sem examinar causas organizacionais e de projeto, como proteção da zona de risco, manutenção, ritmo de produção e dimensionamento da equipe.', ok: true,
      why: 'Correta. Parar no ato inseguro impede o alcance das causas básicas e resulta em medidas de baixa eficácia, tipicamente treinamento e advertência.' },
    { t: 'A investigação é adequada, pois identificou o comportamento que imediatamente antecedeu a lesão.', ok: false,
      why: 'Errada. Identificar a causa imediata é apenas o primeiro passo; a investigação precisa explicar por que aquele comportamento foi possível e necessário.' },
    { t: 'A investigação é adequada, desde que acompanhada de advertência disciplinar ao operador.', ok: false,
      why: 'Errada. A punição desestimula o relato de quase acidentes e degrada a qualidade da informação sobre riscos.' },
    { t: 'A investigação deveria ter sido conduzida exclusivamente pelo médico do trabalho, por envolver lesão corporal.', ok: false,
      why: 'Errada. A investigação é multiprofissional e envolve segurança, produção, manutenção e representação dos trabalhadores.' },
    { t: 'A investigação é dispensável quando a máquina possui certificado de conformidade emitido pelo fabricante.', ok: false,
      why: 'Errada. Certificação não substitui investigação, e a proteção pode ter sido removida, burlada ou ser inadequada à tarefa real.' }
  ],
  comentario: 'Investigação que termina em ato inseguro é investigação incompleta. É preciso separar causas imediatas de causas básicas ou organizacionais e propor medidas na hierarquia de controle, priorizando eliminação e proteção coletiva sobre treinamento e advertência.',
  pegadinha: 'Treinamento como única medida corretiva é sinal de investigação superficial e costuma ser a distratora mais aceita.',
  refs: ['Análise de acidentes — árvore de causas', 'NR-1 — Gerenciamento de Riscos Ocupacionais'] },

{ id: 'q-5.1-030', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Uma equipe de saúde e segurança decide aplicar a técnica de árvore de causas na investigação de um acidente com queda de andaime. Sobre o método, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A árvore de causas parte do evento final e reconstrói, para trás, a rede de fatos necessários que o tornaram possível, evidenciando a multicausalidade em vez de apontar um culpado.', ok: true,
      why: 'Correta. O método é retrospectivo, baseado em fatos e não em julgamentos, e explicita que acidentes resultam da conjunção de várias condições.' },
    { t: 'A árvore de causas hierarquiza os fatores por probabilidade estatística de ocorrência futura.', ok: false,
      why: 'Errada. Essa é a lógica de métodos probabilísticos de análise de risco, e não da árvore de causas, que é reconstrutiva e qualitativa.' },
    { t: 'A árvore de causas exige que se identifique um único fator determinante para orientar a ação corretiva.', ok: false,
      why: 'Errada. O método serve justamente para superar a busca por causa única.' },
    { t: 'A árvore de causas substitui a inspeção do local e a entrevista com os envolvidos, por se basear em documentos.', ok: false,
      why: 'Errada. A coleta de fatos no local e as entrevistas são insumos indispensáveis à construção da árvore.' },
    { t: 'A árvore de causas deve ser aplicada somente a acidentes fatais, por seu custo operacional.', ok: false,
      why: 'Errada. O método se aplica também a acidentes sem afastamento e a quase acidentes, que oferecem aprendizado com menor custo humano.' }
  ],
  comentario: 'A árvore de causas reconstrói a rede de antecedentes necessários ao evento a partir de fatos verificáveis, sem julgamento de conduta. É ferramenta de aprendizagem organizacional e se aplica inclusive a quase acidentes.',
  pegadinha: 'Descrever o método como busca de "causa determinante única" contraria seu próprio fundamento.',
  refs: ['Análise de acidentes — árvore de causas', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-031', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Na análise de um acidente com queimadura química, a equipe registra: contato do antebraço com solução cáustica durante transferência manual entre recipientes; ausência de bomba de transferência; luva inadequada ao agente; e meta de produção elevada com equipe reduzida. Sobre a classificação desses achados, assinale a alternativa CORRETA:',
  alts: [
    { t: 'O contato com a solução é a causa imediata, enquanto ausência de sistema de transferência, seleção inadequada de proteção e pressão por produção são causas básicas ou organizacionais, que devem orientar as medidas corretivas.', ok: true,
      why: 'Correta. As causas básicas explicam por que a situação de risco existia e são as que, corrigidas, previnem a recorrência.' },
    { t: 'Todos os achados são causas imediatas, pois todos estavam presentes no momento do evento.', ok: false,
      why: 'Errada. Simultaneidade não define categoria: causa imediata é o fato que produz diretamente a lesão; as demais condições são antecedentes organizacionais.' },
    { t: 'A meta de produção não pode ser considerada causa de acidente por ser decisão de gestão e não fator técnico.', ok: false,
      why: 'Errada. Organização do trabalho, ritmo e dimensionamento de equipe são fatores de risco reconhecidos e frequentemente decisivos.' },
    { t: 'A seleção inadequada de luva é causa imediata e as demais são consequências dela.', ok: false,
      why: 'Errada. A proteção inadequada é condição antecedente, e não o fato que produziu diretamente a lesão.' },
    { t: 'A classificação em causas imediatas e básicas foi abandonada em favor da atribuição de responsabilidade individual.', ok: false,
      why: 'Errada. A tendência é exatamente a oposta, com foco crescente em fatores organizacionais e sistêmicos.' }
  ],
  comentario: 'Distinga sempre o que aconteceu (causa imediata) do porquê foi possível acontecer (causas básicas ou organizacionais). As medidas eficazes atacam as causas básicas: eliminar a transferência manual, escolher proteção compatível com o agente e revisar ritmo e dimensionamento.',
  pegadinha: 'Tratar a proteção individual inadequada como causa imediata desloca a solução para o trabalhador e mantém o risco na origem.',
  refs: ['Análise de acidentes — causas imediatas e básicas', 'Hierarquia de controles de risco'] },

{ id: 'q-5.1-032', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Concluída a investigação de um acidente com fratura por prensamento, a empresa elabora relatório detalhado com todas as causas identificadas, mas não define responsáveis nem prazos. Seis meses depois, ocorre acidente semelhante no mesmo setor. A falha central do processo foi:',
  alts: [
    { t: 'Não fechar o ciclo da investigação com plano de ação contendo responsável, prazo e verificação posterior de eficácia das medidas implantadas.', ok: true,
      why: 'Correta. Investigação sem plano de ação executado e verificado não altera as condições que produziram o acidente.' },
    { t: 'Não ter aplicado sanção disciplinar aos envolvidos no primeiro evento.', ok: false,
      why: 'Errada. Sanção não corrige condição de risco e prejudica o relato espontâneo de falhas.' },
    { t: 'Ter identificado causas em excesso, o que dispersou a atenção da equipe.', ok: false,
      why: 'Errada. Multicausalidade é característica dos acidentes; o problema não foi identificar causas, mas não agir sobre elas.' },
    { t: 'Não ter aguardado a conclusão da perícia previdenciária antes de investigar.', ok: false,
      why: 'Errada. A investigação interna é independente e deve ser imediata, sob pena de perda de evidências.' },
    { t: 'Ter envolvido a representação dos trabalhadores na investigação, o que atrasou o relatório.', ok: false,
      why: 'Errada. A participação dos trabalhadores qualifica a investigação por trazer o conhecimento do trabalho real.' }
  ],
  comentario: 'O produto da investigação não é o relatório: é a mudança implantada. Plano de ação com responsável, prazo e verificação de eficácia é o que interrompe a recorrência. Relatórios sem execução são fonte de repetição de eventos.',
  pegadinha: 'A recorrência do acidente costuma ser atribuída à falha do trabalhador, quando decorre de ciclo de melhoria não fechado.',
  refs: ['Gestão de SST — ciclo PDCA', 'Análise e prevenção de acidentes'] },

{ id: 'q-5.1-033', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre a investigação e a análise de acidentes do trabalho, assinale a alternativa INCORRETA:',
  alts: [
    { t: 'A finalidade principal da investigação é identificar o responsável pelo evento, de modo a permitir a aplicação de medida disciplinar proporcional.', ok: true,
      why: 'Esta é a afirmação falsa, e por isso deve ser marcada. A finalidade é prevenir a recorrência; a busca de culpados degrada a informação e não altera as condições de risco.' },
    { t: 'Quase acidentes devem ser investigados, pois oferecem aprendizado sobre falhas de barreira sem que tenha havido dano.', ok: false,
      why: 'Afirmação verdadeira, e prática consolidada em gestão de segurança.' },
    { t: 'A participação dos trabalhadores da área é fundamental, pois eles conhecem a diferença entre o trabalho prescrito e o trabalho real.', ok: false,
      why: 'Afirmação verdadeira. O trabalho real é onde as adaptações e os riscos efetivamente aparecem.' },
    { t: 'As medidas corretivas devem seguir a hierarquia de controle, priorizando eliminação e proteção coletiva sobre a proteção individual.', ok: false,
      why: 'Afirmação verdadeira. A hierarquia orienta a escolha das medidas de maior eficácia e menor dependência do comportamento.' },
    { t: 'A investigação deve ocorrer o mais próximo possível do evento, para preservar evidências e memória dos envolvidos.', ok: false,
      why: 'Afirmação verdadeira. O tempo degrada tanto as evidências físicas quanto o relato.' }
  ],
  comentario: 'Investigar é aprender, não punir. A cultura punitiva reduz o relato, esconde quase acidentes e mantém o risco. A boa investigação é precoce, participativa, multicausal e termina em medidas na hierarquia de controle.',
  pegadinha: 'A ideia de disciplina proporcional soa organizada e responsável, mas contraria a lógica preventiva da investigação.',
  refs: ['Cultura de segurança e aprendizagem organizacional', 'NR-1 — Gerenciamento de Riscos Ocupacionais'] },

{ id: 'q-5.1-034', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de frigorífico morre soterrado por carga durante operação de carregamento. Além da comunicação imediata do óbito, o médico do trabalho orienta a empresa quanto às demais providências. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'O acidente fatal deve ser comunicado de imediato à autoridade competente e notificado à vigilância em saúde, devendo o local ser preservado até a liberação pela autoridade, sem prejuízo da investigação interna.', ok: true,
      why: 'Correta. Acidentes fatais têm fluxo próprio, com comunicação imediata, notificação em vigilância e preservação do local para apuração.' },
    { t: 'Basta a comunicação do óbito à Previdência, ficando a notificação à vigilância a critério da empresa.', ok: false,
      why: 'Errada. Acidente fatal é agravo de notificação compulsória, e o fluxo de vigilância não é facultativo.' },
    { t: 'A investigação interna deve aguardar a conclusão do inquérito policial, para não interferir na apuração.', ok: false,
      why: 'Errada. A investigação interna é independente e deve ser conduzida sem prejuízo da apuração oficial, respeitada a preservação do local.' },
    { t: 'A preservação do local é dispensada quando há registro fotográfico feito pela própria empresa.', ok: false,
      why: 'Errada. Registro fotográfico não substitui a preservação física do cenário para exame pela autoridade.' },
    { t: 'A notificação à vigilância substitui a comunicação previdenciária quando o acidente é fatal.', ok: false,
      why: 'Errada. Os fluxos são independentes e cumulativos, também no acidente fatal.' }
  ],
  comentario: 'Acidente grave, fatal ou envolvendo criança e adolescente tem fluxo de notificação imediata à vigilância, além da comunicação previdenciária. Preservação do local e investigação interna independente completam o conjunto de providências.',
  pegadinha: 'Tratar a notificação em vigilância como alternativa à comunicação previdenciária, e não como fluxo paralelo, é o erro plantado.',
  refs: ['Lei nº 8.213/1991 — art. 22', 'Notificação compulsória de acidente de trabalho grave e fatal'] },

{ id: 'q-5.1-035', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Um trabalhador rural sofre amputação traumática de mão em colheitadeira e é levado ao hospital regional. Sobre a notificação em vigilância em saúde desse evento, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Trata-se de acidente de trabalho grave, de notificação compulsória, cuja obrigação alcança o serviço de saúde que presta o atendimento, independentemente de haver ou não vínculo formal de emprego.', ok: true,
      why: 'Correta. A notificação de acidente grave é obrigação dos serviços de saúde e não se condiciona à formalização do vínculo empregatício.' },
    { t: 'A notificação é obrigação exclusiva da empresa empregadora, não cabendo ao hospital notificar.', ok: false,
      why: 'Errada. A notificação compulsória em vigilância recai sobre os serviços de saúde que identificam o agravo.' },
    { t: 'A notificação é dispensada em trabalhador rural informal, por ausência de cobertura previdenciária.', ok: false,
      why: 'Errada. A vigilância em saúde tem alcance universal e independe de vínculo ou cobertura previdenciária.' },
    { t: 'A notificação substitui a investigação do acidente pela vigilância local.', ok: false,
      why: 'Errada. A notificação é o gatilho que deflagra a investigação, e não o seu substituto.' },
    { t: 'A notificação deve aguardar a definição do prognóstico funcional da mão amputada.', ok: false,
      why: 'Errada. A notificação de acidente grave é imediata e não depende de definição de prognóstico.' }
  ],
  comentario: 'Acidente de trabalho grave é agravo de notificação compulsória pelos serviços de saúde, com alcance universal, inclusive para trabalhadores informais e sem vínculo formal. A notificação deflagra a investigação da vigilância no ambiente de trabalho.',
  pegadinha: 'Restringir a notificação ao trabalhador com vínculo formal ignora que a vigilância em saúde cobre toda a população trabalhadora.',
  refs: ['Notificação compulsória de agravos relacionados ao trabalho', 'Vigilância em Saúde do Trabalhador'] },

{ id: 'q-5.1-036', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Adolescente de dezesseis anos, contratado como aprendiz em marcenaria, sofre laceração de mão em serra circular. Sobre as providências, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Além da comunicação de acidente e da notificação em vigilância, o caso demanda apuração específica da adequação da atividade à condição de adolescente, dado o rol de trabalhos proibidos a menores de dezoito anos.', ok: true,
      why: 'Correta. Acidente com criança ou adolescente tem fluxo próprio de notificação e exige verificar se a atividade era permitida à faixa etária.' },
    { t: 'Por se tratar de aprendiz, não há acidente do trabalho, e sim acidente escolar, sem repercussão previdenciária.', ok: false,
      why: 'Errada. O aprendiz é empregado com contrato especial e está coberto pela proteção acidentária.' },
    { t: 'A comunicação de acidente deve ser emitida pela instituição de ensino que encaminhou o adolescente.', ok: false,
      why: 'Errada. A obrigação de comunicar é da empresa empregadora, sem prejuízo dos legitimados subsidiários.' },
    { t: 'A notificação em vigilância é dispensada porque não houve afastamento superior a quinze dias.', ok: false,
      why: 'Errada. Acidente com adolescente é notificável independentemente da duração do afastamento.' },
    { t: 'A operação de serra circular por adolescente é permitida desde que haja supervisão de adulto.', ok: false,
      why: 'Errada. Atividades perigosas e insalubres são vedadas a menores de dezoito anos, e a supervisão não converte a atividade em permitida.' }
  ],
  comentario: 'Acidente com criança ou adolescente é sinal de alerta duplo: exige notificação específica e revisão da legalidade da atividade, uma vez que trabalhos perigosos e insalubres são proibidos a menores de dezoito anos. O aprendiz é empregado e está plenamente coberto.',
  pegadinha: 'Chamar o evento de acidente escolar retira o adolescente da proteção acidentária e é a distratora mais grave do conjunto.',
  refs: ['Proteção ao trabalho do adolescente', 'Notificação compulsória de acidente de trabalho grave'] },

{ id: 'q-5.1-037', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Uma indústria com 400 trabalhadores registra, em determinado ano, 12 acidentes com afastamento e 800.000 horas-homem de exposição ao risco. O gestor quer saber quantos acidentes ocorrem por volume de exposição. O indicador apropriado é:',
  alts: [
    { t: 'Taxa de frequência, que relaciona o número de acidentes ao total de horas-homem de exposição ao risco, permitindo comparar períodos e setores com diferentes contingentes e jornadas.', ok: true,
      why: 'Correta. A taxa de frequência usa como denominador as horas-homem de exposição, o que neutraliza diferenças de tamanho e de jornada.' },
    { t: 'Taxa de gravidade, que expressa quantos acidentes ocorrem por volume de exposição.', ok: false,
      why: 'Errada. A taxa de gravidade mede o peso das consequências em dias perdidos e debitados, e não a frequência dos eventos.' },
    { t: 'Taxa de incidência, que utiliza as horas-homem trabalhadas como denominador.', ok: false,
      why: 'Errada. A taxa de incidência usa o número de trabalhadores expostos como denominador, e não as horas de exposição.' },
    { t: 'Taxa de letalidade, que relaciona acidentes fatais ao total de horas trabalhadas.', ok: false,
      why: 'Errada. Letalidade relaciona óbitos ao número de casos, não ao volume de exposição.' },
    { t: 'Prevalência de acidentes, obtida pela razão entre acidentes e a população total do município.', ok: false,
      why: 'Errada. O conceito é inadequado ao objeto: acidente é evento agudo, medido por incidência e por taxas de exposição, não por prevalência populacional.' }
  ],
  comentario: 'Taxa de frequência responde "quantos acidentes acontecem por volume de exposição"; taxa de gravidade responde "quão sérios são"; taxa de incidência compara por número de trabalhadores. Escolher o denominador correto é o que a prova cobra.',
  pegadinha: 'Trocar horas-homem por número de trabalhadores confunde taxa de frequência com taxa de incidência.',
  refs: ['Indicadores de acidentalidade', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-038', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Ao consolidar os indicadores anuais, o serviço de segurança de uma mineradora observa que a taxa de gravidade aumentou de forma expressiva, embora o número de acidentes tenha caído. Sobre a interpretação, assinale a alternativa CORRETA:',
  alts: [
    { t: 'O cenário indica menos eventos, porém de consequências mais sérias, e exige atenção prioritária aos riscos de alto potencial de dano, ainda que raros.', ok: true,
      why: 'Correta. Gravidade crescente com frequência decrescente aponta para eventos de alta severidade, cuja prevenção depende de barreiras específicas e não de campanhas gerais.' },
    { t: 'O cenário é contraditório, pois taxa de gravidade e taxa de frequência necessariamente variam no mesmo sentido.', ok: false,
      why: 'Errada. Os indicadores medem dimensões diferentes e podem divergir; é justamente essa divergência que traz informação.' },
    { t: 'O cenário indica melhora global, pois o número de acidentes é o indicador que melhor traduz o desempenho.', ok: false,
      why: 'Errada. Contagem isolada de eventos ignora a severidade e pode mascarar deterioração do desempenho.' },
    { t: 'O cenário decorre necessariamente de subnotificação de acidentes leves, sem qualquer alteração real de risco.', ok: false,
      why: 'Errada. Subnotificação é hipótese a investigar, mas afirmá-la como causa necessária é conclusão sem base.' },
    { t: 'A taxa de gravidade só se altera quando há óbito, de modo que o dado indica ocorrência de acidente fatal.', ok: false,
      why: 'Errada. A taxa de gravidade incorpora dias perdidos por afastamento e dias debitados por incapacidades permanentes, não apenas óbitos.' }
  ],
  comentario: 'Frequência e gravidade são dimensões independentes: poucos eventos muito graves e muitos eventos leves pedem intervenções distintas. A leitura conjunta dos indicadores, e não a contagem isolada de eventos, é o que orienta a priorização.',
  pegadinha: 'Assumir que os dois indicadores caminham juntos elimina exatamente a informação que a divergência traz.',
  refs: ['Indicadores de acidentalidade', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-039', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Ao calcular a taxa de gravidade de uma empresa que teve, no período, um acidente com incapacidade permanente total e diversos afastamentos temporários, o técnico pergunta como computar o caso da incapacidade permanente. A resposta CORRETA é:',
  alts: [
    { t: 'Morte e incapacidade permanente total são convertidas em número fixo de dias debitados, que se somam aos dias efetivamente perdidos nos afastamentos temporários para compor o indicador.', ok: true,
      why: 'Correta. A conversão em dias debitados permite que consequências permanentes entrem no cálculo, que de outro modo só refletiria o tempo de afastamento.' },
    { t: 'A incapacidade permanente total não entra no cálculo, por não gerar dias de afastamento contáveis.', ok: false,
      why: 'Errada. Excluí-la faria com que o pior desfecho possível não repercutisse no indicador de gravidade.' },
    { t: 'A incapacidade permanente total deve ser computada apenas pelos dias de afastamento até a alta pericial.', ok: false,
      why: 'Errada. Isso subestimaria grosseiramente o peso do evento, equiparando-o a um afastamento temporário longo.' },
    { t: 'A incapacidade permanente total é computada na taxa de frequência, e não na de gravidade.', ok: false,
      why: 'Errada. O evento entra na frequência como um acidente, mas sua severidade se expressa na taxa de gravidade.' },
    { t: 'A incapacidade permanente total deve ser convertida em dias debitados proporcionais ao salário do acidentado.', ok: false,
      why: 'Errada. A conversão é técnica e padronizada por tipo de dano, sem qualquer relação com remuneração.' }
  ],
  comentario: 'A taxa de gravidade soma dias perdidos por afastamento temporário e dias debitados por incapacidades permanentes e óbito, convertidos por convenção técnica padronizada. Sem essa conversão, o indicador perderia sensibilidade justamente aos piores desfechos.',
  pegadinha: 'Deixar a incapacidade permanente fora do denominador de gravidade é o erro que torna o indicador insensível ao dano irreversível.',
  refs: ['Indicadores de acidentalidade — dias perdidos e debitados', 'Guia 5.1 — Acidentes do Trabalho'] }
,

{ id: 'q-5.1-040', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Duas empresas do mesmo ramo, uma com 200 e outra com 2.000 trabalhadores, querem comparar seu desempenho em acidentalidade em um congresso setorial, mas não dispõem do registro confiável de horas-homem trabalhadas. O indicador mais adequado para essa comparação é:',
  alts: [
    { t: 'Taxa de incidência, que utiliza o número de trabalhadores expostos como denominador e dispensa o registro de horas-homem.', ok: true,
      why: 'Correta. A taxa de incidência foi concebida para comparações entre empresas e setores quando o denominador de horas não está disponível ou não é confiável.' },
    { t: 'Taxa de frequência, pois é o único indicador que permite comparação entre empresas de portes diferentes.', ok: false,
      why: 'Errada. A taxa de frequência exige justamente o dado de horas-homem, que o cenário informa não existir de forma confiável.' },
    { t: 'Número absoluto de acidentes, por ser o dado mais objetivo e menos sujeito a manipulação.', ok: false,
      why: 'Errada. O número absoluto favorece sistematicamente a empresa menor e não permite comparação válida.' },
    { t: 'Taxa de gravidade, pois converte todos os desfechos em uma medida única.', ok: false,
      why: 'Errada. A taxa de gravidade mede severidade e também depende de denominador de exposição; não substitui a medida de ocorrência.' },
    { t: 'Percentual de trabalhadores com atestado médico no período, por refletir o impacto real na produção.', ok: false,
      why: 'Errada. Atestados englobam causas comuns e ocupacionais e não constituem indicador de acidentalidade.' }
  ],
  comentario: 'Escolha do denominador: horas-homem de exposição para taxa de frequência e gravidade; número de trabalhadores expostos para taxa de incidência. Quando o registro de horas é frágil, a incidência é a alternativa metodologicamente honesta.',
  pegadinha: 'Comparar números absolutos entre empresas de portes distintos é o erro elementar que a questão testa por trás da escolha do indicador.',
  refs: ['Indicadores de acidentalidade', 'Epidemiologia aplicada à saúde do trabalhador'] },

{ id: 'q-5.1-041', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Após assalto à mão armada no caixa da loja em que trabalha, uma operadora desenvolve transtorno de estresse pós-traumático, com incapacidade para o trabalho por quatro meses. A empresa entende que, por não ter havido lesão corporal, não se trata de acidente do trabalho. A avaliação CORRETA é:',
  alts: [
    { t: 'Há acidente do trabalho, pois o conceito legal abrange a perturbação funcional que cause perda ou redução, permanente ou temporária, da capacidade para o trabalho, não se exigindo lesão anatômica visível.', ok: true,
      why: 'Correta. O conceito legal contempla expressamente a perturbação funcional, o que abrange repercussões psíquicas incapacitantes decorrentes do evento laboral.' },
    { t: 'Não há acidente do trabalho, pois a definição legal exige lesão corporal objetivamente demonstrável.', ok: false,
      why: 'Errada. Lesão corporal e perturbação funcional são hipóteses alternativas no conceito legal, e não requisitos cumulativos.' },
    { t: 'Há doença do trabalho, mas não acidente, pois o quadro psíquico se instalou ao longo de semanas.', ok: false,
      why: 'Errada. O quadro decorre de evento súbito e determinado ocorrido no exercício do trabalho, o que caracteriza acidente, ainda que a expressão clínica se desenvolva depois.' },
    { t: 'Não há acidente do trabalho, pois o assalto é ato de terceiro estranho à empresa.', ok: false,
      why: 'Errada. Ato de terceiro no local e horário de trabalho está entre as hipóteses equiparadas.' },
    { t: 'Há acidente do trabalho apenas se houver registro de boletim de ocorrência policial.', ok: false,
      why: 'Errada. O boletim é meio de prova útil, mas não é requisito de caracterização.' }
  ],
  comentario: 'O conceito legal de acidente do trabalho abrange lesão corporal ou perturbação funcional que cause morte, perda ou redução, permanente ou temporária, da capacidade laborativa. Repercussão psíquica incapacitante decorrente de evento laboral é acidente do trabalho.',
  pegadinha: 'Exigir lesão anatômica visível é a leitura empobrecida do conceito e exclui indevidamente os agravos psíquicos.',
  refs: ['Lei nº 8.213/1991 — arts. 19 e 21', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-042', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Um trabalhador de 62 anos, escriturário, apresenta artrose de joelhos e pleiteia reconhecimento de doença do trabalho. O perito verifica atividade predominantemente sentada, sem sobrecarga articular relevante. Sobre a análise, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A lei exclui do conceito de doença do trabalho a doença degenerativa e a inerente a grupo etário, salvo comprovação de que resultou de exposição ou contato direto determinado pela natureza do trabalho.', ok: true,
      why: 'Correta. A exclusão legal existe, mas é condicionada: comprovada a contribuição das condições especiais do trabalho, o enquadramento se restabelece.' },
    { t: 'Toda doença degenerativa é automaticamente reconhecida como doença do trabalho quando o trabalhador tem longo tempo de vínculo.', ok: false,
      why: 'Errada. Tempo de vínculo não substitui a demonstração de exposição e de capacidade de agravamento pela atividade.' },
    { t: 'A exclusão legal das doenças degenerativas é absoluta e não admite qualquer exceção.', ok: false,
      why: 'Errada. A própria lei ressalva a hipótese de a doença resultar de exposição ou contato determinado pela natureza do trabalho.' },
    { t: 'A doença inerente a grupo etário é sempre reconhecida quando o trabalhador ultrapassa sessenta anos.', ok: false,
      why: 'Errada. A idade avançada não cria presunção de origem ocupacional; ao contrário, integra a hipótese de exclusão condicionada.' },
    { t: 'A ausência de sobrecarga articular na função impede que se cogite de concausa em qualquer hipótese.', ok: false,
      why: 'Errada. A concausa deve ser sempre examinada, embora no cenário descrito faltem elementos de exposição que a sustentem.' }
  ],
  comentario: 'A lei exclui do conceito de doença do trabalho a doença degenerativa, a inerente a grupo etário, a que não produz incapacidade e a endêmica adquirida por habitante da região, salvo comprovação de que resultaram de exposição determinada pela natureza do trabalho. A exclusão é condicionada, não absoluta.',
  pegadinha: 'A prova alterna entre "exclusão absoluta" e "reconhecimento automático"; ambas são falsas, pois a lei trabalha com ressalva.',
  refs: ['Lei nº 8.213/1991 — art. 20', 'Guia 5.2 — Nexo Causal'] },

{ id: 'q-5.1-043', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhadora de laboratório de anatomia patológica desenvolve quadro respiratório crônico atribuído à exposição a agente químico específico do processo, condição não constante das listas oficiais de doenças ocupacionais. Sobre o enquadramento, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A doença pode ser equiparada a doença do trabalho quando resulta de condições especiais em que o trabalho é executado e com ele se relaciona diretamente, mesmo não constando das listas.', ok: true,
      why: 'Correta. A lei prevê expressamente a possibilidade de reconhecimento de agravo não listado, desde que demonstrada a relação direta com as condições especiais do trabalho.' },
    { t: 'A ausência da doença nas listas oficiais impede definitivamente o reconhecimento como doença do trabalho.', ok: false,
      why: 'Errada. As listas orientam e facilitam o reconhecimento, mas não esgotam as hipóteses possíveis.' },
    { t: 'O reconhecimento depende de alteração prévia da lista por norma regulamentadora específica.', ok: false,
      why: 'Errada. A previsão legal de reconhecimento de agravo não listado é autoaplicável ao caso concreto.' },
    { t: 'O caso deve ser enquadrado obrigatoriamente como acidente típico, por envolver agente químico.', ok: false,
      why: 'Errada. Exposição prolongada a agente químico com instalação progressiva caracteriza doença, e não evento súbito.' },
    { t: 'A doença só pode ser reconhecida se houver nexo epidemiológico entre a atividade econômica e o código diagnóstico.', ok: false,
      why: 'Errada. O nexo epidemiológico é um dos caminhos de reconhecimento; a análise do caso concreto é outro, plenamente válido.' }
  ],
  comentario: 'As listas de doenças ocupacionais não são exaustivas: agravo não listado pode ser reconhecido quando resulta de condições especiais do trabalho e com elas se relaciona diretamente. É a válvula que permite acompanhar novas exposições e novas tecnologias.',
  pegadinha: 'Tratar a lista como numerus clausus é a leitura mais comum e é incorreta.',
  refs: ['Lei nº 8.213/1991 — art. 20', 'Lista de Doenças Relacionadas ao Trabalho'] },

{ id: 'q-5.1-044', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Ao explicar a diferença entre doença profissional e doença do trabalho a residentes, o preceptor apresenta dois casos: silicose em jateador de areia e perda auditiva em operador de máquina ruidosa em setor não classicamente ruidoso. A distinção conceitual CORRETA é:',
  alts: [
    { t: 'Doença profissional é a produzida ou desencadeada pelo exercício peculiar a determinada atividade, típica dela; doença do trabalho é a adquirida em função de condições especiais em que o trabalho é realizado e com ele se relaciona diretamente.', ok: true,
      why: 'Correta. A distinção está na tipicidade: uma decorre da profissão em si, a outra das condições concretas em que o trabalho é executado.' },
    { t: 'Doença profissional é a que exige nexo epidemiológico, e doença do trabalho é a que exige nexo individual.', ok: false,
      why: 'Errada. A distinção entre elas é de natureza conceitual da exposição, e não de tipo de nexo técnico aplicável.' },
    { t: 'Doença profissional é a que gera afastamento, e doença do trabalho é a que não gera.', ok: false,
      why: 'Errada. Repercussão sobre a capacidade não integra a definição de nenhuma das duas categorias.' },
    { t: 'Doença profissional é a que consta de lista oficial, e doença do trabalho é a que não consta de lista alguma.', ok: false,
      why: 'Errada. Ambas podem constar das listas oficiais; a distinção não é de listagem.' },
    { t: 'Doença profissional é aquela reconhecida judicialmente, e doença do trabalho a reconhecida administrativamente.', ok: false,
      why: 'Errada. A via de reconhecimento não define a categoria clínica e legal do agravo.' }
  ],
  comentario: 'Doença profissional decorre do exercício peculiar a determinada atividade; doença do trabalho decorre das condições especiais em que o trabalho é executado. Ambas se equiparam a acidente do trabalho para todos os efeitos legais.',
  pegadinha: 'Diferenciar as duas pela existência de lista ou pela via de reconhecimento é confusão frequente e sem base conceitual.',
  refs: ['Lei nº 8.213/1991 — art. 20', 'Guia 4.1 — Patologia do Trabalho'] },

{ id: 'q-5.1-045', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Empregado de empresa prestadora de serviços de limpeza sofre queda de escada dentro do estabelecimento da empresa contratante e fratura o punho. Surge dúvida sobre quem deve emitir a comunicação do acidente. A orientação CORRETA é:',
  alts: [
    { t: 'A obrigação de comunicar é do empregador do trabalhador acidentado, ou seja, da empresa prestadora de serviços, sem prejuízo das responsabilidades da contratante quanto às condições do ambiente.', ok: true,
      why: 'Correta. A comunicação vincula-se ao vínculo empregatício; a contratante responde pelas condições do ambiente em que a atividade é executada.' },
    { t: 'A obrigação é da empresa contratante, pois o acidente ocorreu em seu estabelecimento.', ok: false,
      why: 'Errada. O local do evento não desloca a obrigação, que segue o vínculo de emprego.' },
    { t: 'A obrigação é solidária, cabendo emissão em duplicidade por ambas as empresas.', ok: false,
      why: 'Errada. Duplicidade de registro do mesmo evento distorce estatísticas e não é a solução prevista.' },
    { t: 'Não há obrigação de comunicar, pois o trabalhador terceirizado não integra o quadro da contratante.', ok: false,
      why: 'Errada. O trabalhador terceirizado é empregado da prestadora e está plenamente coberto pela proteção acidentária.' },
    { t: 'A obrigação recai sobre o tomador apenas quando a atividade terceirizada for a atividade-fim da contratante.', ok: false,
      why: 'Errada. A distinção entre atividade-meio e atividade-fim não altera quem é o empregador para efeito da comunicação.' }
  ],
  comentario: 'A comunicação segue o vínculo empregatício: emite quem é o empregador. Isso não afasta a responsabilidade da contratante pelas condições do ambiente onde o serviço é prestado, nem sua obrigação de participar da investigação e das medidas corretivas.',
  pegadinha: 'A intuição de que "quem manda no ambiente comunica" é forte e incorreta para efeito da comunicação previdenciária.',
  refs: ['Lei nº 8.213/1991 — art. 22', 'NR-1 — responsabilidades de contratante e contratada'] },

{ id: 'q-5.1-046', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Analista em regime de teletrabalho, durante o horário previsto para a prestação de serviços e enquanto participava de reunião por videoconferência, sofre queda da cadeira de escritório fornecida pela empresa e fratura o cóccix. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'Trata-se de acidente do trabalho, pois o evento ocorreu durante a execução do trabalho, sendo o domicílio, nessa modalidade, o local em que a atividade é prestada.', ok: true,
      why: 'Correta. No teletrabalho, o critério decisivo é a execução da atividade laboral, e não o endereço em que ela ocorre.' },
    { t: 'Não se trata de acidente do trabalho, pois eventos ocorridos no domicílio do trabalhador são sempre de natureza comum.', ok: false,
      why: 'Errada. O domicílio, no teletrabalho, funciona como local de prestação do serviço durante a jornada.' },
    { t: 'Trata-se de acidente de trajeto, por ausência de deslocamento até o estabelecimento da empresa.', ok: false,
      why: 'Errada. Não houve percurso algum, e a ausência de deslocamento não cria hipótese de trajeto.' },
    { t: 'Trata-se de acidente do trabalho apenas se a empresa tiver realizado inspeção prévia do posto domiciliar.', ok: false,
      why: 'Errada. A ausência de inspeção pode caracterizar falha da empresa, mas não descaracteriza o acidente.' },
    { t: 'Não se trata de acidente do trabalho porque a empresa não exerce controle direto sobre o ambiente domiciliar.', ok: false,
      why: 'Errada. A ausência de controle direto reforça o dever de orientação e avaliação do posto, e não afasta a caracterização.' }
  ],
  comentario: 'No teletrabalho, o que caracteriza o acidente é a ocorrência durante a execução da atividade laboral, e não o endereço. A empresa mantém deveres de orientação, fornecimento de condições adequadas e avaliação do posto, cuja omissão agrava sua responsabilidade.',
  pegadinha: 'A ausência de controle sobre o ambiente é apresentada como excludente, quando na verdade é fonte de dever adicional.',
  refs: ['Lei nº 8.213/1991 — art. 19', 'Teletrabalho e saúde ocupacional'] },

{ id: 'q-5.1-047', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Uma empresa custeia curso técnico em outra cidade para operadores, dentro de seu plano de qualificação. Durante o deslocamento para o curso, um dos operadores sofre acidente automobilístico com politraumatismo. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'Trata-se de acidente do trabalho por equiparação, pois a viagem para estudo financiada pela empresa, dentro de seus planos de capacitação, integra as hipóteses protegidas.', ok: true,
      why: 'Correta. A lei equipara expressamente a viagem a serviço, inclusive para estudo custeado pela empresa em seus planos de melhor capacitação.' },
    { t: 'Trata-se de acidente comum, pois curso de qualificação não é prestação de serviço à empresa.', ok: false,
      why: 'Errada. A hipótese de equiparação abrange explicitamente o deslocamento para estudo financiado pela empresa.' },
    { t: 'Trata-se de acidente de trajeto, por se tratar de deslocamento entre cidades.', ok: false,
      why: 'Errada. O percurso protegido como trajeto é o de residência para trabalho e vice-versa.' },
    { t: 'Trata-se de acidente do trabalho apenas se o curso for obrigatório por norma regulamentadora.', ok: false,
      why: 'Errada. A obrigatoriedade normativa do curso não é condição da equiparação.' },
    { t: 'Trata-se de acidente do trabalho somente se o veículo pertencer à empresa.', ok: false,
      why: 'Errada. A equiparação da viagem a serviço independe do meio de locomoção.' }
  ],
  comentario: 'Viagem a serviço, incluída a viagem para estudo custeado pela empresa dentro de seus planos de capacitação, é hipótese expressa de equiparação, independentemente do meio de locomoção e da obrigatoriedade normativa do curso.',
  pegadinha: 'A ideia de que capacitação é benefício ao trabalhador, e não serviço à empresa, leva ao enquadramento errado.',
  refs: ['Lei nº 8.213/1991 — art. 21', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-048', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre o conceito legal de acidente do trabalho e suas repercussões, assinale a alternativa INCORRETA:',
  alts: [
    { t: 'Somente se caracteriza acidente do trabalho quando há redução permanente da capacidade laborativa, excluindo-se do conceito as reduções temporárias.', ok: true,
      why: 'Esta é a afirmação falsa, e por isso deve ser marcada. O conceito legal abrange expressamente a perda ou redução permanente ou temporária da capacidade para o trabalho.' },
    { t: 'A doença profissional e a doença do trabalho equiparam-se a acidente do trabalho para todos os efeitos legais.', ok: false,
      why: 'Afirmação verdadeira. A equiparação é expressa e alcança benefícios, garantia de emprego e demais repercussões.' },
    { t: 'A morte decorrente do evento integra o conceito legal de acidente do trabalho.', ok: false,
      why: 'Afirmação verdadeira. O óbito é um dos desfechos previstos na definição.' },
    { t: 'A perturbação funcional, mesmo sem lesão anatômica evidente, pode caracterizar acidente do trabalho.', ok: false,
      why: 'Afirmação verdadeira. Lesão corporal e perturbação funcional são hipóteses alternativas.' },
    { t: 'O acidente do trabalho pode ocorrer fora do estabelecimento da empresa, nas hipóteses legalmente equiparadas.', ok: false,
      why: 'Afirmação verdadeira. Trajeto, viagem a serviço e execução de ordem fora do local são exemplos.' }
  ],
  comentario: 'O conceito legal é deliberadamente amplo: lesão corporal ou perturbação funcional, com morte, perda ou redução permanente ou temporária da capacidade. Restringir a redução ao caráter permanente amputa metade da definição.',
  pegadinha: 'A palavra "permanente" isolada é o gatilho da armadilha; o texto legal traz permanente ou temporária.',
  refs: ['Lei nº 8.213/1991 — arts. 19 a 21', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-049', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'O setor de pessoal de uma indústria informa que passou a transmitir a comunicação de acidente por evento eletrônico próprio do sistema de escrituração digital das obrigações trabalhistas e previdenciárias. Sobre essa mudança, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A transmissão eletrônica alterou o meio de envio da informação, mantendo inalterados o dever de comunicar, os prazos e o rol de legitimados subsidiários.', ok: true,
      why: 'Correta. A digitalização é mudança de suporte e de fluxo de dados, sem revogar o regime legal da comunicação.' },
    { t: 'Com a transmissão eletrônica, a comunicação passou a ser facultativa nos acidentes sem afastamento.', ok: false,
      why: 'Errada. A obrigatoriedade permanece independentemente de afastamento, qualquer que seja o meio de transmissão.' },
    { t: 'A transmissão eletrônica extinguiu a legitimidade do médico assistente e do sindicato para comunicar.', ok: false,
      why: 'Errada. Os legitimados subsidiários permanecem, com canais próprios de registro.' },
    { t: 'A transmissão eletrônica ampliou para trinta dias o prazo de comunicação pela empresa.', ok: false,
      why: 'Errada. O prazo permanece até o primeiro dia útil seguinte, com comunicação imediata em caso de morte.' },
    { t: 'A transmissão eletrônica dispensa a notificação em vigilância em saúde, pois integra as bases de dados.', ok: false,
      why: 'Errada. Os fluxos previdenciário e de vigilância permanecem distintos e cumulativos.' }
  ],
  comentario: 'A migração para o registro eletrônico não modificou o núcleo do dever: comunicar mesmo sem afastamento, no prazo até o primeiro dia útil seguinte, de imediato em caso de morte, com legitimados subsidiários preservados e sem substituir a notificação em vigilância.',
  pegadinha: 'Mudanças de sistema costumam ser apresentadas como se alterassem prazos ou obrigações substantivas, o que não ocorre.',
  refs: ['Lei nº 8.213/1991 — art. 22', 'eSocial — eventos de segurança e saúde no trabalho'] },

{ id: 'q-5.1-050', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Ao auditar o programa de saúde de uma empresa, o médico do trabalho identifica que apenas acidentes com afastamento superior a quinze dias foram comunicados nos últimos três anos. A consequência técnica mais relevante dessa prática é:',
  alts: [
    { t: 'Subnotificação sistemática, que compromete os indicadores de acidentalidade, retarda a identificação de riscos e prejudica o resguardo de direitos do trabalhador em caso de agravamento futuro.', ok: true,
      why: 'Correta. Filtrar por afastamento cria viés grave nos dados e retira do sistema justamente os eventos sentinela de menor gravidade que anunciam eventos maiores.' },
    { t: 'Nenhuma, pois eventos sem afastamento não repercutem em benefício e, portanto, não precisam ser registrados.', ok: false,
      why: 'Errada. A obrigação de comunicar independe de afastamento, e o registro tem funções que vão além do benefício imediato.' },
    { t: 'Melhora aparente da taxa de gravidade, que passa a refletir com mais fidelidade o desempenho real.', ok: false,
      why: 'Errada. A melhora é artificial e decorre de omissão de registro, não de redução de risco.' },
    { t: 'Aumento da alíquota de financiamento dos benefícios acidentários, por excesso de registros.', ok: false,
      why: 'Errada. A subnotificação tende a produzir efeito inverso no curto prazo, mascarando o desempenho real da empresa.' },
    { t: 'Substituição legítima do registro individual pela análise agregada de atestados médicos.', ok: false,
      why: 'Errada. Atestados não distinguem origem ocupacional e não substituem a comunicação de acidente.' }
  ],
  comentario: 'Comunicar apenas acidentes com afastamento prolongado é subnotificação disfarçada de critério. Perde-se o evento sentinela, distorcem-se os indicadores e expõe-se o trabalhador ao risco de não ter o nexo reconhecido quando a lesão se agravar meses depois.',
  pegadinha: 'A prática é frequentemente justificada como racionalização administrativa, o que a torna especialmente difícil de identificar como erro.',
  refs: ['Lei nº 8.213/1991 — art. 22', 'Vigilância em Saúde do Trabalhador'] },

{ id: 'q-5.1-051', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Empregado sofre acidente de percurso a caminho do trabalho, afasta-se por sessenta dias com benefício previdenciário e retorna. A empresa pretende dispensá-lo sem justa causa dois meses após o retorno. Assinale a alternativa CORRETA:',
  alts: [
    { t: 'Como o acidente de percurso é equiparado a acidente do trabalho, o benefício tem natureza acidentária e o contrato deve ser mantido por período mínimo de doze meses contados da cessação do benefício.', ok: true,
      why: 'Correta. A equiparação produz todos os efeitos do acidente do trabalho, inclusive a garantia de emprego contada da alta.' },
    { t: 'Não há garantia de emprego, pois o acidente de percurso não gera benefício de natureza acidentária.', ok: false,
      why: 'Errada. A equiparação legal atribui ao percurso os mesmos efeitos do acidente típico.' },
    { t: 'A garantia existe, mas conta-se a partir da data do acidente, já estando exaurida no cenário descrito.', ok: false,
      why: 'Errada. A contagem se inicia na cessação do benefício, e não na data do evento.' },
    { t: 'A garantia depende de a empresa fornecer transporte, pois só nesse caso o percurso é protegido.', ok: false,
      why: 'Errada. A proteção do percurso independe do meio de locomoção e de quem fornece o transporte.' },
    { t: 'A garantia se aplica apenas se o trabalhador retornar com restrições funcionais documentadas.', ok: false,
      why: 'Errada. A existência de restrição não é requisito da garantia de emprego decorrente do afastamento acidentário.' }
  ],
  comentario: 'Acidente de percurso é equiparado e, portanto, produz benefício acidentário, garantia de emprego contada da cessação, manutenção do fundo de garantia no afastamento e demais repercussões. Nada disso depende do meio de transporte nem de sequela residual.',
  pegadinha: 'A questão reúne dois pontos de alto rendimento em uma só armadilha: natureza do percurso e marco inicial da estabilidade.',
  refs: ['Lei nº 8.213/1991 — arts. 21 e 118', 'Guia 5.1 — Acidentes do Trabalho'] },

{ id: 'q-5.1-052', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Trabalhador sofre acidente típico com afastamento de vinte e cinco dias. O setor financeiro questiona a quem cabe o pagamento nesse período. A informação CORRETA é:',
  alts: [
    { t: 'Cabe à empresa o pagamento do salário integral nos primeiros quinze dias de afastamento, passando o benefício previdenciário a ser devido a partir do décimo sexto dia.', ok: true,
      why: 'Correta. A responsabilidade da empresa pelos primeiros quinze dias é regra do afastamento por incapacidade, e o benefício inicia-se na sequência.' },
    { t: 'Cabe ao órgão previdenciário o pagamento desde o primeiro dia, por se tratar de acidente do trabalho.', ok: false,
      why: 'Errada. A natureza acidentária dispensa carência e altera a espécie do benefício, mas não desloca a responsabilidade pelos primeiros quinze dias.' },
    { t: 'Cabe à empresa o pagamento de todo o período, por se tratar de evento ocorrido em suas dependências.', ok: false,
      why: 'Errada. A responsabilidade da empresa é limitada ao período inicial definido em lei.' },
    { t: 'O pagamento é rateado proporcionalmente entre empresa e órgão previdenciário durante todo o afastamento.', ok: false,
      why: 'Errada. Não existe rateio proporcional; há sucessão de responsáveis no tempo.' },
    { t: 'Não há pagamento nos primeiros quinze dias, que constituem período de carência do benefício.', ok: false,
      why: 'Errada. Carência é número mínimo de contribuições, conceito distinto do período de responsabilidade da empresa.' }
  ],
  comentario: 'Nos afastamentos por incapacidade, a empresa remunera os primeiros quinze dias e o benefício previdenciário incide a partir do décimo sexto. Esse marco temporal não se confunde com carência, nem interfere na obrigação de comunicar o acidente.',
  pegadinha: 'Chamar os primeiros quinze dias de carência é confusão terminológica comum e explorada em prova.',
  refs: ['Lei nº 8.213/1991 — arts. 59 a 63', 'Guia 5.5 — Incapacidade laborativa'] },

{ id: 'q-5.1-053', tema: '5.1', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Uma empresa apresenta ao médico do trabalho o seguinte conjunto de decisões tomadas após acidente com afastamento: não emitiu comunicação por discordar do nexo; registrou o evento apenas em planilha interna; e orientou o trabalhador a buscar benefício por doença comum. Sobre esse conjunto, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Todas as três decisões são inadequadas, pois a comunicação é obrigatória e independe da concordância da empresa quanto ao nexo, o registro interno não a substitui e o direcionamento a benefício comum prejudica direitos do trabalhador.', ok: true,
      why: 'Correta. As três condutas se combinam para produzir subnotificação, perda de garantia de emprego e de manutenção do fundo de garantia, além de expor a empresa a penalidade.' },
    { t: 'Apenas o registro em planilha interna é inadequado, sendo as demais decisões defensáveis.', ok: false,
      why: 'Errada. A omissão da comunicação e o direcionamento a benefício comum são igualmente indevidos.' },
    { t: 'As decisões são adequadas, pois a empresa pode escolher a espécie de benefício que entende cabível.', ok: false,
      why: 'Errada. A espécie do benefício decorre da natureza do agravo apurada pela perícia, e não de escolha do empregador.' },
    { t: 'Apenas o direcionamento a benefício comum é inadequado, pois a comunicação depende de reconhecimento pericial prévio.', ok: false,
      why: 'Errada. A comunicação não depende de reconhecimento pericial; ela antecede o juízo da perícia.' },
    { t: 'As decisões seriam adequadas se a empresa tivesse notificado o evento à vigilância em saúde.', ok: false,
      why: 'Errada. A notificação em vigilância é fluxo paralelo e não supre a comunicação previdenciária.' }
  ],
  comentario: 'Questão de síntese: a comunicação é obrigatória, independe de concordância quanto ao nexo, independe de afastamento e de perícia, não é substituída por registro interno nem por notificação em vigilância, e a espécie do benefício não é objeto de escolha do empregador.',
  pegadinha: 'A distratora que aceita duas das três condutas premia quem identifica apenas o erro mais visível e perde os demais.',
  refs: ['Lei nº 8.213/1991 — arts. 21, 22 e 118', 'Guia 5.1 — Acidentes do Trabalho'] }
,

{ id: 'q-5.2-010', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de fundição há dezoito anos apresenta quadro respiratório progressivo com achados radiológicos compatíveis com pneumoconiose. O perito reúne histórico ocupacional detalhado, laudos de avaliação ambiental com concentrações elevadas do agente e afasta as principais causas alternativas. O elemento do raciocínio de nexo que a fase de exclusão de outras causas cumpre é:',
  alts: [
    { t: 'Reduzir a probabilidade de que a doença se explique por causa não ocupacional, fortalecendo a inferência causal sem exigir prova de causa única.', ok: true,
      why: 'Correta. A exclusão razoável de causas alternativas aumenta a força da inferência; não se exige demonstrar que o trabalho foi a única causa possível.' },
    { t: 'Demonstrar que o trabalho é a causa única e exclusiva da doença, requisito indispensável ao reconhecimento.', ok: false,
      why: 'Errada. Causa única nunca foi requisito; a lei se satisfaz com contribuição direta, e a figura da concausa confirma isso.' },
    { t: 'Substituir a avaliação da exposição, que se torna dispensável quando as causas alternativas são afastadas.', ok: false,
      why: 'Errada. Exclusão de causas alternativas não cria exposição; a demonstração da exposição continua sendo a base do raciocínio.' },
    { t: 'Dispensar a análise de latência, uma vez que o tempo de exposição já foi documentado.', ok: false,
      why: 'Errada. Tempo de exposição e latência são grandezas distintas: uma diz quanto tempo se expôs, a outra se o intervalo até a doença é compatível.' },
    { t: 'Definir o grau de incapacidade laborativa decorrente da doença reconhecida.', ok: false,
      why: 'Errada. Nexo e incapacidade são juízos independentes; a exclusão de causas alternativas nada informa sobre a capacidade para o trabalho.' }
  ],
  comentario: 'O roteiro do nexo percorre exposição, temporalidade, latência, plausibilidade biológica e exclusão de outras causas. A exclusão fortalece a inferência, mas não converte o raciocínio em exigência de causa única nem substitui os demais elementos.',
  pegadinha: 'A exigência de exclusividade causal é a distorção mais comum e contraria diretamente a lógica da concausa.',
  refs: ['Guia 5.2 — Nexo Causal', 'Lei nº 8.213/1991 — art. 21'] },

{ id: 'q-5.2-011', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador admitido há quatro meses em empresa de reciclagem apresenta mesotelioma pleural. Relata trabalho anterior de vinte anos em desmanche de telhas de amianto. Sobre a análise de nexo, assinale a alternativa CORRETA:',
  alts: [
    { t: 'O critério de latência é decisivo: o intervalo entre a exposição e a doença é longo, o que aponta a exposição pregressa como relevante e afasta a atribuição ao vínculo atual.', ok: true,
      why: 'Correta. A latência prolongada é característica do agravo, e o raciocínio de nexo deve buscar a exposição compatível no tempo, ainda que em empregador anterior.' },
    { t: 'O nexo deve ser atribuído ao vínculo atual, pois é o empregador em que o diagnóstico foi feito.', ok: false,
      why: 'Errada. O momento do diagnóstico não indica onde ocorreu a exposição causal; confundir os dois é erro grave de raciocínio.' },
    { t: 'A ausência de exposição no vínculo atual afasta a natureza ocupacional da doença.', ok: false,
      why: 'Errada. A doença permanece ocupacional; muda apenas a identificação do período de exposição responsável.' },
    { t: 'A latência longa enfraquece o nexo, pois quanto maior o intervalo menor a plausibilidade causal.', ok: false,
      why: 'Errada. Para esse tipo de agravo, latência longa é exatamente o esperado; latência curta é que seria incompatível.' },
    { t: 'O nexo só pode ser reconhecido se houver registro de comunicação de acidente emitida pelo empregador anterior.', ok: false,
      why: 'Errada. A ausência de comunicação anterior não impede o reconhecimento, e a comunicação pode ser emitida pelos legitimados subsidiários.' }
  ],
  comentario: 'Latência é o critério que reorganiza casos de exposição em múltiplos vínculos: procura-se a exposição temporalmente compatível com a história natural da doença, e não o empregador em que o diagnóstico foi firmado.',
  pegadinha: 'Atribuir o nexo ao empregador atual apenas por ser o vínculo vigente é erro conceitual grave e frequente.',
  refs: ['Guia 5.2 — Nexo Causal', 'Doenças relacionadas ao asbesto'] },

{ id: 'q-5.2-012', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhadora relata dermatite palmar iniciada duas semanas após passar a manusear produto de limpeza concentrado, com melhora nas férias e recidiva ao retornar. Sobre os elementos do raciocínio de nexo presentes nesse relato, assinale a alternativa CORRETA:',
  alts: [
    { t: 'O relato reúne exposição documentável, temporalidade adequada e melhora ao afastamento com recidiva à reexposição, conjunto de forte valor para sustentar o nexo.', ok: true,
      why: 'Correta. A relação temporal com o início da atividade e o comportamento de melhora e recidiva compõem evidência clínica robusta de relação com o trabalho.' },
    { t: 'A melhora durante as férias é irrelevante, por se tratar de informação subjetiva do trabalhador.', ok: false,
      why: 'Errada. A resposta ao afastamento e à reexposição é dado clínico de grande valor no raciocínio ocupacional, especialmente em dermatoses e asma.' },
    { t: 'A latência de duas semanas é incompatível com dermatose ocupacional, que exige anos de exposição.', ok: false,
      why: 'Errada. Dermatoses de contato podem se manifestar em dias ou semanas; latência longa é característica de outros grupos de agravos.' },
    { t: 'O nexo só pode ser afirmado após teste de contato positivo, sem o qual não há elemento suficiente.', ok: false,
      why: 'Errada. O teste auxilia a distinguir mecanismo irritativo de alérgico, mas o nexo se constrói com o conjunto de exposição, temporalidade e evolução.' },
    { t: 'A ausência de outros casos no setor exclui a relação com o trabalho.', ok: false,
      why: 'Errada. Suscetibilidade individual explica casos isolados, e ausência de surto coletivo não afasta o nexo individual.' }
  ],
  comentario: 'Melhora no afastamento com recidiva à reexposição é um dos achados de maior valor prático no raciocínio de nexo, sobretudo em dermatoses e em asma. Latência compatível varia com o agravo: dias em irritação de contato, décadas em neoplasias.',
  pegadinha: 'Exigir latência longa para toda doença ocupacional generaliza indevidamente o modelo das pneumoconioses e das neoplasias.',
  refs: ['Guia 5.2 — Nexo Causal', 'Dermatoses ocupacionais'] },

{ id: 'q-5.2-013', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Ao aplicar critérios de causalidade a um caso de perda auditiva em trabalhador exposto a ruído, o perito verifica que quanto maior o tempo e a intensidade da exposição, maior o rebaixamento auditivo observado na coorte da empresa. O critério de causalidade evidenciado é:',
  alts: [
    { t: 'Gradiente dose-resposta, que descreve o aumento do efeito com o aumento da magnitude ou da duração da exposição.', ok: true,
      why: 'Correta. A relação crescente entre exposição e efeito é um dos critérios de maior peso na inferência causal.' },
    { t: 'Plausibilidade biológica, que consiste na observação de maior efeito nos mais expostos.', ok: false,
      why: 'Errada. Plausibilidade diz respeito à existência de mecanismo biológico conhecido, e não ao padrão quantitativo observado.' },
    { t: 'Consistência, que se refere à relação entre intensidade da exposição e magnitude do efeito.', ok: false,
      why: 'Errada. Consistência é a reprodução do achado em diferentes estudos, populações e contextos.' },
    { t: 'Temporalidade, que exige que o efeito aumente com a dose acumulada.', ok: false,
      why: 'Errada. Temporalidade é apenas a exigência de que a exposição preceda a doença.' },
    { t: 'Especificidade, que estabelece que cada agente produza um único efeito.', ok: false,
      why: 'Errada. A especificidade é critério fraco e frequentemente violado, pois agentes produzem múltiplos efeitos e efeitos têm múltiplas causas.' }
  ],
  comentario: 'Distinga os critérios: temporalidade (exposição antes), latência (intervalo compatível), plausibilidade (mecanismo conhecido), força de associação (magnitude do risco), gradiente dose-resposta (mais exposição, mais efeito), consistência (reprodutibilidade) e exclusão de alternativas.',
  pegadinha: 'Trocar gradiente dose-resposta por plausibilidade biológica é a confusão mais frequente na lista de critérios.',
  refs: ['Guia 5.2 — Nexo Causal', 'Epidemiologia — critérios de causalidade'] },

{ id: 'q-5.2-014', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Um assistente técnico sustenta em parecer que "não há nexo, pois o trabalhador não está incapacitado para o trabalho". Sobre esse argumento, assinale a alternativa CORRETA:',
  alts: [
    { t: 'O argumento é tecnicamente equivocado, pois nexo e incapacidade são juízos independentes: pode haver doença relacionada ao trabalho sem incapacidade, e incapacidade sem qualquer relação com o trabalho.', ok: true,
      why: 'Correta. A independência entre os juízos é ponto central: a ausência de incapacidade não informa nada sobre a origem do agravo.' },
    { t: 'O argumento é correto, pois sem incapacidade não há dano a ser reparado nem nexo a reconhecer.', ok: false,
      why: 'Errada. O reconhecimento do nexo tem efeitos próprios, como registro do agravo, intervenção no ambiente e resguardo de direitos futuros.' },
    { t: 'O argumento é correto apenas nas doenças de instalação lenta, nas quais a incapacidade é pressuposto do diagnóstico.', ok: false,
      why: 'Errada. Incapacidade não integra o diagnóstico de nenhuma doença ocupacional.' },
    { t: 'O argumento é equivocado porque incapacidade e nexo são a mesma coisa em perícia previdenciária.', ok: false,
      why: 'Errada. Não são a mesma coisa: o perito examina separadamente a existência de incapacidade e a sua origem.' },
    { t: 'O argumento é correto se o trabalhador estiver em atividade plena, pois a atividade plena comprova ausência de agravo.', ok: false,
      why: 'Errada. Trabalhar não é prova de ausência de doença; muitos agravos ocupacionais cursam com atividade preservada por longos períodos.' }
  ],
  comentario: 'Nexo responde de onde veio o agravo; incapacidade responde o que ele faz com a capacidade de trabalhar. São perguntas distintas, com respostas independentes, e a prova cobra exatamente essa separação.',
  pegadinha: 'A fórmula "sem incapacidade, sem nexo" soa pericial e é conceitualmente falsa.',
  refs: ['Guia 5.2 — Nexo Causal', 'Guia 5.5 — Incapacidade laborativa'] },

{ id: 'q-5.2-015', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre o raciocínio de nexo causal em medicina do trabalho, assinale a alternativa INCORRETA:',
  alts: [
    { t: 'A demonstração do nexo exige que a doença seja atribuível exclusivamente ao trabalho, sem qualquer participação de fatores individuais ou extralaborais.', ok: true,
      why: 'Esta é a afirmação falsa, e por isso deve ser marcada. A lei se contenta com a contribuição direta do trabalho, admitindo expressamente a concorrência de outros fatores.' },
    { t: 'A caracterização da exposição, quanto à intensidade e à duração, é elemento essencial do raciocínio.', ok: false,
      why: 'Afirmação verdadeira. Sem exposição demonstrável, o raciocínio causal não se sustenta.' },
    { t: 'A latência incompatível com a história natural da doença é argumento forte para afastar o nexo.', ok: false,
      why: 'Afirmação verdadeira. Incompatibilidade temporal é dos argumentos mais sólidos para negar relação com o trabalho.' },
    { t: 'A plausibilidade biológica exige a existência de mecanismo conhecido pelo qual o agente possa produzir a lesão observada.', ok: false,
      why: 'Afirmação verdadeira. É o critério que ancora o raciocínio no conhecimento fisiopatológico disponível.' },
    { t: 'A ausência de nexo direto não encerra a análise, devendo o perito examinar a hipótese de concausa antes de concluir.', ok: false,
      why: 'Afirmação verdadeira. A análise de concausa é etapa obrigatória antes de afastar a relação com o trabalho.' }
  ],
  comentario: 'A exigência de exclusividade causal é o erro estrutural do tema: a lei fala em contribuição direta, e não em causa única. Todo o instituto da concausa existe para tornar essa distinção operacional.',
  pegadinha: 'A palavra "exclusivamente" é o marcador da distorção; quando aparecer em enunciado de nexo, desconfie.',
  refs: ['Guia 5.2 — Nexo Causal', 'Lei nº 8.213/1991 — art. 21'] },

{ id: 'q-5.2-016', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Ao avaliar trabalhador com hipoacusia, o perito constata perda auditiva assimétrica, com componente condutivo e história de otite crônica na infância, em exposição a ruído de intensidade moderada. O passo mais adequado do raciocínio de nexo é:',
  alts: [
    { t: 'Aprofundar a exclusão de causas alternativas e caracterizar quantitativamente a exposição, pois o padrão audiométrico descrito não é o esperado da lesão por ruído ocupacional.', ok: true,
      why: 'Correta. Padrão incompatível exige revisão do diagnóstico diferencial e melhor caracterização da exposição antes de qualquer conclusão.' },
    { t: 'Reconhecer o nexo de imediato, pois há exposição a ruído documentada na função.', ok: false,
      why: 'Errada. Exposição isolada não basta quando o padrão clínico é incompatível com o agravo esperado.' },
    { t: 'Afastar definitivamente qualquer relação com o trabalho, pois há causa não ocupacional identificada.', ok: false,
      why: 'Errada. A existência de causa não ocupacional não encerra a análise: resta examinar contribuição do trabalho como concausa.' },
    { t: 'Solicitar apenas nova audiometria, pois a repetição do exame resolve a questão do nexo.', ok: false,
      why: 'Errada. Repetir exame confirma o achado, mas não substitui a caracterização da exposição e o diagnóstico diferencial.' },
    { t: 'Encaminhar diretamente à avaliação de incapacidade, pois o nexo é irrelevante nesse momento.', ok: false,
      why: 'Errada. O nexo define a espécie do benefício e as repercussões acessórias, não podendo ser deixado de lado.' }
  ],
  comentario: 'Quando o padrão clínico não corresponde ao esperado do agente, o raciocínio pede diagnóstico diferencial mais rigoroso e melhor caracterização da exposição. Achar causa não ocupacional não encerra a análise: falta examinar a concausa.',
  pegadinha: 'Concluir pela ausência de nexo assim que se identifica uma causa não ocupacional é atalho que ignora a etapa da concausa.',
  refs: ['Guia 5.2 — Nexo Causal', 'Otorrinolaringologia ocupacional'] },

{ id: 'q-5.2-017', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de indústria de acumuladores elétricos apresenta quadro compatível com intoxicação por chumbo, com indicadores biológicos alterados. O perito reconhece a relação com o trabalho a partir da associação, prevista em listas técnicas oficiais, entre o agente e a entidade mórbida. O tipo de nexo aplicado é:',
  alts: [
    { t: 'Nexo técnico profissional ou do trabalho, que decorre da associação entre agente ou fator de risco e doença, conforme as listas técnicas oficiais.', ok: true,
      why: 'Correta. O reconhecimento a partir da associação agente-doença prevista em lista é a marca do nexo profissional ou do trabalho.' },
    { t: 'Nexo técnico epidemiológico previdenciário, pois há associação entre a atividade da empresa e a doença.', ok: false,
      why: 'Errada. O nexo epidemiológico opera pelo cruzamento entre atividade econômica e entidade mórbida, e não pela associação agente-doença.' },
    { t: 'Nexo técnico individual, pois o perito examinou o trabalhador e seus exames.', ok: false,
      why: 'Errada. O exame do segurado integra qualquer perícia; o nexo individual é o que se estabelece quando os anteriores não se aplicam e a conclusão se apoia na análise do caso concreto.' },
    { t: 'Concausa preexistente, pois há suscetibilidade individual à absorção do metal.', ok: false,
      why: 'Errada. Não há no cenário condição anterior descrita, e o reconhecimento se dá por associação direta agente-doença.' },
    { t: 'Nexo presumido absoluto, insuscetível de revisão administrativa.', ok: false,
      why: 'Errada. Não existe categoria de nexo presumido absoluto no sistema previdenciário brasileiro.' }
  ],
  comentario: 'Os três nexos técnicos: profissional ou do trabalho (agente × doença, por listas), epidemiológico (atividade econômica × entidade mórbida, com presunção relativa) e individual (análise do caso concreto). Identificar qual foi aplicado é questão recorrente.',
  pegadinha: 'A presença de exame do segurado leva muitos a marcar nexo individual, quando o mecanismo aplicado foi a lista agente-doença.',
  refs: ['Guia 5.2 — Nexo Causal', 'Decreto nº 3.048/1999 — anexo de doenças ocupacionais'] },

{ id: 'q-5.2-018', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Sobre o nexo técnico profissional ou do trabalho, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Fundamenta-se em listas que relacionam agentes ou fatores de risco de natureza ocupacional às doenças que podem produzir, permitindo o reconhecimento quando comprovada a exposição correspondente.', ok: true,
      why: 'Correta. É o nexo construído sobre a associação previamente reconhecida entre agente e doença, dependente da demonstração da exposição.' },
    { t: 'Dispensa a comprovação de exposição ao agente, bastando a compatibilidade diagnóstica com a lista.', ok: false,
      why: 'Errada. A lista associa agente e doença; sem exposição demonstrada ao agente, a associação não se aplica ao caso.' },
    { t: 'Aplica-se apenas quando a empresa emite comunicação de acidente reconhecendo o nexo.', ok: false,
      why: 'Errada. O reconhecimento independe da postura da empresa quanto à comunicação.' },
    { t: 'É estabelecido exclusivamente pelo médico assistente, sem participação da perícia.', ok: false,
      why: 'Errada. O médico assistente pode e deve apontar a relação com o trabalho, mas o reconhecimento para fins de benefício é feito na perícia.' },
    { t: 'Tem natureza estatística e resulta do cruzamento entre atividade econômica e diagnóstico.', ok: false,
      why: 'Errada. Essa é a descrição do nexo epidemiológico, não do profissional.' }
  ],
  comentario: 'O nexo profissional ou do trabalho é o nexo "de dicionário": parte do agente ou da doença listada e exige demonstração da exposição concreta. É distinto do epidemiológico, que é estatístico e parte da atividade econômica.',
  pegadinha: 'Dispensar a comprovação da exposição transforma a lista em presunção automática, o que ela não é.',
  refs: ['Guia 5.2 — Nexo Causal', 'Decreto nº 3.048/1999 — anexo de doenças ocupacionais'] },

{ id: 'q-5.2-019', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Uma empresa de abate e processamento de carnes é surpreendida com a concessão de benefícios de natureza acidentária a trabalhadores com síndrome do túnel do carpo, sem que tenha emitido qualquer comunicação de acidente. O gestor pergunta se pode contestar. A orientação CORRETA é:',
  alts: [
    { t: 'A empresa pode contestar administrativamente, pois a presunção decorrente do nexo epidemiológico é relativa e admite prova em contrário quanto à inexistência de relação entre o agravo e o trabalho.', ok: true,
      why: 'Correta. A presunção é relativa e existe via administrativa própria para que a empresa demonstre a ausência de relação.' },
    { t: 'Não cabe contestação, pois a presunção decorrente do cruzamento estatístico é absoluta.', ok: false,
      why: 'Errada. A troca de presunção relativa por absoluta é a armadilha mais frequente do tema.' },
    { t: 'Não cabe contestação porque a empresa deixou de emitir a comunicação de acidente, o que a impede de discutir o nexo.', ok: false,
      why: 'Errada. O nexo epidemiológico existe justamente para operar sem comunicação; a omissão não retira o direito de contestar.' },
    { t: 'A contestação é possível apenas na via judicial, não existindo procedimento administrativo para tanto.', ok: false,
      why: 'Errada. Existe via administrativa específica para essa contestação, sem prejuízo do acesso à via judicial.' },
    { t: 'A contestação exige perícia particular contratada pela empresa junto ao trabalhador, com exame físico obrigatório.', ok: false,
      why: 'Errada. A empresa não tem prerrogativa de submeter o segurado a exame para desconstituir benefício previdenciário.' }
  ],
  comentario: 'O nexo epidemiológico opera pelo cruzamento entre atividade econômica e entidade mórbida, dispensa comunicação de acidente e gera presunção relativa, contestável administrativamente pela empresa. Nada nele é automático e definitivo.',
  pegadinha: 'A palavra "absoluta" aplicada a essa presunção é sempre falsa e é a distratora campeã do tema.',
  refs: ['Lei nº 8.213/1991 — art. 21-A', 'Guia 5.2 — Nexo Causal'] },

{ id: 'q-5.2-020', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'O gerente de saúde ocupacional afirma que "o nexo epidemiológico só se aplica quando a empresa emite comunicação de acidente, pois é ela que informa a natureza do evento à Previdência". Sobre essa afirmação, assinale a alternativa CORRETA:',
  alts: [
    { t: 'A afirmação é falsa, pois o nexo epidemiológico foi concebido exatamente para operar independentemente da comunicação, corrigindo a subnotificação dos agravos relacionados ao trabalho.', ok: true,
      why: 'Correta. Condicionar o mecanismo à comunicação anularia sua finalidade, que é reconhecer a natureza acidentária apesar da omissão de registro.' },
    { t: 'A afirmação é verdadeira, pois sem comunicação a Previdência não dispõe de informação sobre o vínculo entre doença e trabalho.', ok: false,
      why: 'Errada. O cruzamento se dá entre a atividade econômica registrada da empresa e o diagnóstico informado no benefício, sem depender da comunicação.' },
    { t: 'A afirmação é verdadeira apenas para doenças osteomusculares, nas quais a comunicação é indispensável.', ok: false,
      why: 'Errada. Não há essa restrição por grupo diagnóstico; o mecanismo é geral.' },
    { t: 'A afirmação é falsa, mas apenas porque a comunicação pode ser emitida por outros legitimados.', ok: false,
      why: 'Errada. A justificativa é insuficiente: o mecanismo dispensa a comunicação de qualquer origem, e não apenas a da empresa.' },
    { t: 'A afirmação é verdadeira, pois o médico perito não pode reconhecer nexo sem documento emitido pelo empregador.', ok: false,
      why: 'Errada. O perito reconhece nexo com base na análise técnica disponível, sem depender de documento do empregador.' }
  ],
  comentario: 'Dispensar a comunicação é o traço distintivo do nexo epidemiológico. Ele opera sobre dados administrativos já existentes — atividade econômica da empresa e diagnóstico do benefício — precisamente porque a subnotificação torna a comunicação um filtro pouco confiável.',
  pegadinha: 'A distratora que acerta a conclusão pela razão errada testa se o candidato compreende o mecanismo, e não apenas o resultado.',
  refs: ['Lei nº 8.213/1991 — art. 21-A', 'Guia 5.2 — Nexo Causal'] },

{ id: 'q-5.2-021', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Sobre o nexo técnico epidemiológico previdenciário, assinale a alternativa INCORRETA:',
  alts: [
    { t: 'Uma vez aplicado, impede que o perito analise as circunstâncias individuais do caso, ficando vinculado ao resultado do cruzamento estatístico.', ok: true,
      why: 'Esta é a afirmação falsa, e por isso deve ser marcada. A presunção é relativa e não elimina a análise do caso concreto pela perícia.' },
    { t: 'Resulta do cruzamento entre a atividade econômica da empresa e a entidade mórbida do segurado.', ok: false,
      why: 'Afirmação verdadeira, e é a definição do mecanismo.' },
    { t: 'Independe da emissão de comunicação de acidente do trabalho.', ok: false,
      why: 'Afirmação verdadeira. Foi criado para operar apesar da subnotificação.' },
    { t: 'Gera presunção relativa, admitindo contestação administrativa pela empresa.', ok: false,
      why: 'Afirmação verdadeira e ponto central do tema.' },
    { t: 'Sua aplicação repercute na natureza do benefício concedido, com efeitos em garantia de emprego e recolhimento do fundo de garantia.', ok: false,
      why: 'Afirmação verdadeira. Reconhecida a natureza acidentária, seguem-se as repercussões próprias.' }
  ],
  comentario: 'Presunção relativa significa exatamente que a análise individual permanece possível: nem a empresa fica sem defesa, nem o perito fica algemado ao cruzamento. O mecanismo desloca o ônus, não elimina o exame do caso.',
  pegadinha: 'A ideia de vinculação obrigatória do perito ao resultado estatístico transforma presunção relativa em absoluta por outras palavras.',
  refs: ['Lei nº 8.213/1991 — art. 21-A', 'Guia 5.2 — Nexo Causal'] },

{ id: 'q-5.2-022', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador de escritório de contabilidade apresenta epicondilite lateral. Não há associação entre a atividade econômica da empresa e o diagnóstico nas listas epidemiológicas, e o agravo não decorre de agente listado. A perícia, contudo, documenta digitação intensiva por longas jornadas, com posto inadequado, e ausência de causas alternativas. O reconhecimento cabível se dá por:',
  alts: [
    { t: 'Nexo técnico individual, estabelecido pela análise do caso concreto quando não incidem os mecanismos de lista nem o cruzamento epidemiológico.', ok: true,
      why: 'Correta. O nexo individual é a via residual e plenamente válida, apoiada no exame do segurado e na documentação da exposição real.' },
    { t: 'Ausência de nexo, pois a inexistência de previsão em lista e de associação epidemiológica esgota as possibilidades de reconhecimento.', ok: false,
      why: 'Errada. As listas e o cruzamento estatístico não esgotam o reconhecimento; a análise individual permanece disponível.' },
    { t: 'Nexo técnico epidemiológico, uma vez que a atividade envolve movimentos repetitivos.', ok: false,
      why: 'Errada. O mecanismo epidemiológico depende da associação registrada entre atividade econômica e entidade mórbida, que o cenário afirma não existir.' },
    { t: 'Nexo técnico profissional, pois a digitação é agente de risco listado.', ok: false,
      why: 'Errada. O cenário afirma expressamente que o agravo não decorre de agente listado para aquela exposição.' },
    { t: 'Concausa superveniente, pois a atividade agravou condição já existente.', ok: false,
      why: 'Errada. Não há no cenário condição prévia descrita nem evento posterior somando-se ao curso do dano.' }
  ],
  comentario: 'O nexo individual é a via que o perito percorre quando lista e cruzamento estatístico não resolvem o caso. É o raciocínio clínico-ocupacional puro: exposição real documentada, temporalidade, plausibilidade e exclusão de alternativas.',
  pegadinha: 'Concluir pela ausência de nexo quando falham os dois primeiros mecanismos é o erro que a questão persegue.',
  refs: ['Guia 5.2 — Nexo Causal', 'LER/DORT — avaliação ocupacional'] },

{ id: 'q-5.2-023', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'intermediario',
  enunciado: 'Ao instruir um caso de suspeita de doença relacionada ao trabalho, o perito reúne análise ergonômica do posto, laudo de avaliação ambiental, prontuário do serviço médico da empresa, relatório do médico assistente e exame do segurado. Sobre o valor desses elementos no estabelecimento do nexo individual, assinale a alternativa CORRETA:',
  alts: [
    { t: 'Todos compõem a instrução, cabendo ao perito integrá-los e fundamentar a conclusão, sem que qualquer documento isolado vincule automaticamente o resultado.', ok: true,
      why: 'Correta. A conclusão pericial resulta da integração fundamentada das evidências, e nenhum documento isolado tem força vinculante automática.' },
    { t: 'O relatório do médico assistente vincula o perito, por ser o profissional que acompanha o paciente.', ok: false,
      why: 'Errada. O relatório é peça relevante da instrução, mas o perito conclui com autonomia técnica.' },
    { t: 'A análise ergonômica é irrelevante ao nexo, por tratar de condições e não de doença.', ok: false,
      why: 'Errada. A caracterização da exposição é justamente o alicerce do nexo, e a análise ergonômica é sua principal fonte em agravos osteomusculares.' },
    { t: 'O prontuário do serviço médico da empresa não pode ser utilizado, por conter dados sigilosos.', ok: false,
      why: 'Errada. O acesso a documentos médicos na perícia observa regras próprias de sigilo, mas não é vedado ao exame pericial pertinente.' },
    { t: 'O exame do segurado é dispensável quando há documentação ambiental completa.', ok: false,
      why: 'Errada. O exame do periciado é elemento essencial e insubstituível da avaliação pericial.' }
  ],
  comentario: 'A instrução do nexo individual combina caracterização da exposição, documentos assistenciais e exame do segurado. O perito integra e fundamenta; nenhum documento vincula automaticamente, e nenhum substitui o exame do periciado.',
  pegadinha: 'Atribuir força vinculante ao relatório do assistente confunde os papéis de assistente e perito.',
  refs: ['Guia 5.2 — Nexo Causal', 'Guia 5.4 — Perícia Médica'] },

{ id: 'q-5.2-024', tema: '5.2', tipo: 'autoral', fonte: null, nivel: 'dificil',
  enunciado: 'Trabalhador exposto a sílica há vinte e cinco anos desenvolve silicose. Aplicando a classificação de Schilling à relação entre trabalho e doença nesse caso, o enquadramento CORRETO é:',
  alts: [
    { t: 'Grupo em que o trabalho é causa necessária, sem a qual a doença não se desenvolveria, situação das doenças profissionais legalmente reconhecidas e das intoxicações específicas.', ok: true,
      why: 'Correta. A silicose depende da exposição à sílica: sem exposição ocupacional ao agente, a doença não ocorre, caracterizando causa necessária.' },
    { t: 'Grupo em que o trabalho é fator contributivo, mas não necessário, como ocorre nas doenças de causa múltipla.', ok: false,
      why: 'Errada. Esse grupo reúne agravos de causa múltipla em que o trabalho concorre, o que não descreve a relação entre sílica e silicose.' },
    { t: 'Grupo em que o trabalho é provocador de distúrbio latente ou agravador de doença já estabelecida.', ok: false,
      why: 'Errada. Esse grupo descreve situações de desencadeamento ou agravamento, e não de causa necessária.' },
    { t: 'Não se aplica a classificação de Schilling às pneumoconioses, restrita que é aos agravos osteomusculares.', ok: false,
      why: 'Errada. A classificação é geral e se aplica a qualquer agravo relacionado ao trabalho.' },
    { t: 'Grupo específico das doenças de notificação compulsória, definido pela obrigatoriedade de notificação.', ok: false,
      why: 'Errada. A classificação organiza o papel causal do trabalho, e não a obrigação de notificar.' }
  ],
  comentario: 'Schilling organiza a relação trabalho-doença em três grupos: trabalho como causa necessária; trabalho como fator contributivo em doença de causa múltipla; e trabalho como provocador de distúrbio latente ou agravador de doença preexistente. Silicose é exemplo clássico do primeiro.',
  pegadinha: 'A classificação descreve o papel causal do trabalho, não a gravidade nem a obrigatoriedade de notificação do agravo.',
  refs: ['Classificação de Schilling', 'Lista de Doenças Relacionadas ao Trabalho'] }

/* FIM-LOTE */
);
